#[test]
fn clock_at_is_monotone_in_both_scales() {
    let (a, b) = (Clock::at(1_000), Clock::at(2_000));
    assert_eq!(b.mono.checked_sub(a.mono), Some(Duration::from_secs(1)));
    assert_eq!(
