        assert!(record.autostart && record.effective_autostart());
        assert_eq!(core.settings().dispatch_runner, Some(id));
        assert_eq!(spawns(&e, id), 1);
        assert!(e.iter().any(|e| matches!(e, Effect::Save(_))));
