// --- fixtures

fn project(name: &str) -> Project {
    let t = Clock::at(0).wall;
    Project {
        id: ProjectId::new(),
        name: name.into(),
        root: PathBuf::from("/tmp/proj"),
        tags: vec![],
        notes: String::new(),
        pinned: vec![],
