        shown: Vec::new(),
        created: t,
        last_active: t,
        space: SpaceId::DEFAULT,
        op: None,
        env_sets: Vec::new(),
    }
}

fn record(project: ProjectId, kind: SessionKind, order: u32) -> SessionRecord {
    let t = Clock::at(0).wall;
    SessionRecord {
        id: RecordId::new(),
        project,
        name: format!("s{order}"),
        kind,
        cwd: PathBuf::from("/tmp/proj"),
        launch: match kind {
            SessionKind::Agent(_) | SessionKind::Shell => Launch::Shell,
            SessionKind::Command | SessionKind::Service => Launch::Command {
                command: "npm run dev".into(),
                shell: "/bin/zsh".into(),
            },
        },
        env_profile: None,
        created: t,
        last_seen: t,
        notes: String::new(),
        resume: None,
        autostart: false,
        layout: super::model::CardLayout { order, group: None },
        activity: Activity::Unknown,
        activity_reason: None,
        last_event_at: None,
        last_exit: None,
        not_resumable: false,
        scrollback: None,
        source: None,
        approved_hash: None,
        discard: None,
        runs: Vec::new(),
        outputs: Vec::new(),
        op: None,
