    #[test]
    fn a_quiet_agent_stalls_the_run_once_and_the_mark_lifts_when_it_moves() {
        let (mut core, run, _, reviewer, _) = started();
        let quiet_since = |secs: u64| HostStatus {
            last_activity: Some(Clock::at(secs * 1000).wall),
            ..running(reviewer)
        };
        // Quiet for a minute: still working as far as anyone can tell.
        core.dispatch(
            AppAction::HostListed(vec![quiet_since(140)]),
            Clock::at(200_000),
        );
        core.dispatch(AppAction::Tick, Clock::at(200_000));
        assert!(!core.stalled(run));
        assert!(core.notice().is_none());
        // Past the stall threshold: noticed once, the agent reads as
        // waiting on the user.
        core.dispatch(AppAction::Tick, Clock::at(261_000));
        assert!(core.stalled(run));
        let text = core.notice().expect("a notice").text.clone();
        assert!(
            text.contains("plan review") && text.contains("2 min"),
            "{text}"
        );
        assert_eq!(core.card_state(reviewer), CardState::WaitingOnYou);
        core.dispatch(AppAction::DismissNotice, Clock::at(262_000));
        core.dispatch(AppAction::Tick, Clock::at(263_000));
        assert!(core.notice().is_none(), "said once");
        // Output again: the mark lifts, and a later stall is noticed anew.
        core.dispatch(
            AppAction::HostListed(vec![quiet_since(262)]),
            Clock::at(264_000),
        );
        core.dispatch(AppAction::Tick, Clock::at(264_000));
        assert!(!core.stalled(run));
        assert_eq!(core.card_state(reviewer), CardState::Working);
        core.dispatch(AppAction::Tick, Clock::at(400_000));
        assert!(core.stalled(run));
        assert!(core.notice().is_some());
    }

    #[test]
    fn an_exited_agent_fails_the_run_and_continue_relaunches_it() {
        let (mut core, run, _, reviewer, _) = started();
        core.dispatch(
            AppAction::HostListed(vec![exited(reviewer, Some(1))]),
            Clock::at(200),
        );
        let effects = core.dispatch(AppAction::Tick, Clock::at(201));
        assert!(matches!(run_of(&core).state, RunState::Failed(ref why) if why.contains("exited")));
        assert!(
            !effects
                .iter()
                .any(|e| matches!(e, Effect::ProbeRoundFile { .. }))
        );
        let effects = core.dispatch(AppAction::ContinueWorkflow(run), Clock::at(300));
        assert_eq!(run_of(&core).state, RunState::AwaitingFeedback);
        // The dead pane is cleared and the reviewer resumed, with the
        // first prompt on its command line again.
        assert!(effects.iter().any(|e| matches!(e, Effect::Kill(_))));
        assert!(
            effects
                .iter()
                .any(|e| matches!(e, Effect::CheckTranscript { id, .. } if *id == reviewer))
        );
        core.dispatch(
            AppAction::TranscriptChecked {
                id: reviewer,
                exists: true,
            },
            Clock::at(310),
        );
        let effects = core.dispatch(
            AppAction::LaunchPrepared {
                id: reviewer,
                result: Ok(AgentLaunch {
                    argv: vec!["codex".into(), "resume".into(), "r-1".into()],
                    env: vec![],
                    resume: None,
                }),
            },
            Clock::at(320),
        );
        let argv = spawn_argv(&effects);
        assert_eq!(argv.len(), 4);
        assert!(argv[3].contains("plan.feedback-1.md"), "{argv:?}");
    }

    /// A hook event for `id`, at `at_ms` on both clocks.
    fn hook(core: &mut AppCore, id: RecordId, kind: EventKind, at_ms: u64) {
        core.dispatch(
            AppAction::Events(vec![SessionEvent {
                record_id: Some(id),
                ..event(kind, at_ms)
            }]),
            Clock::at(at_ms),
        );
    }

    fn stop(core: &mut AppCore, id: RecordId, at_ms: u64) {
        hook(
            core,
            id,
            EventKind::Stopped {
                last_message: None,
                pending: None,
            },
            at_ms,
        );
    }

    /// A probe that finds the awaited file missing.
    fn missing(core: &mut AppCore, run: WorkflowId, at_ms: u64) -> Vec<Effect> {
        let path = core.workflow(run).unwrap().awaited_file().unwrap().clone();
        core.dispatch(
            AppAction::RoundFileProbed {
                run,
                path,
                found: None,
            },
            Clock::at(at_ms),
        )
    }

    /// Milliseconds after the stop at `stop_ms` when the grace is over.
    fn past_grace(stop_ms: u64) -> u64 {
        stop_ms + u64::try_from(STOP_GRACE.as_millis()).unwrap()
    }

    #[test]
    fn a_reviewer_that_stops_without_its_file_fails_the_run_after_the_grace() {
        let (mut core, run, _, reviewer, _) = started();
        assert_eq!(
            run_of(&core).rounds[0].feedback_asked,
            Some(Clock::at(100).wall)
        );
        stop(&mut core, reviewer, 5_000);
        missing(&mut core, run, past_grace(5_000) - 1_000);
        assert_eq!(run_of(&core).state, RunState::AwaitingFeedback, "in grace");
        let effects = missing(&mut core, run, past_grace(5_000));
        assert!(
            matches!(&run_of(&core).state, RunState::Failed(why)
                if why.contains("stopped without writing") && why.ends_with("plan.feedback-1.md")),
            "{:?}",
            run_of(&core).state
        );
        assert!(saves(&effects) > 0);
        let view = core.run_view(run).unwrap();
        assert!(matches!(
            view.state,
            switchboard_control::RunState::Paused { failed: true, .. }
        ));
    }

    fn stop_listing(core: &mut AppCore, id: RecordId, at_ms: u64, pending: StopPending) {
        hook(
            core,
            id,
            EventKind::Stopped {
                last_message: None,
                pending: Some(pending),
            },
            at_ms,
        );
    }

    fn wakeup(fire_ms: u64) -> StopPending {
        StopPending {
            tasks: vec![],
            wakeups: vec![super::wakeup_at(fire_ms)],
        }
    }

    #[test]
    fn a_reviewer_holding_on_a_wakeup_fails_only_after_it_has_passed() {
        let (mut core, run, _, reviewer, _) = started();
        stop_listing(&mut core, reviewer, 5_000, wakeup(95_000));
        missing(&mut core, run, past_grace(5_000));
        assert_eq!(run_of(&core).state, RunState::AwaitingFeedback, "held");
        missing(&mut core, run, past_grace(95_000) - 1_000);
        assert_eq!(run_of(&core).state, RunState::AwaitingFeedback, "held");
        missing(&mut core, run, past_grace(95_000));
        assert!(
            matches!(&run_of(&core).state, RunState::Failed(why) if why.contains("stopped without writing")),
            "{:?}",
            run_of(&core).state
        );
    }

    #[test]
    fn a_held_stop_whose_pane_is_gone_fails_after_the_grace() {
        let (mut core, run, _, reviewer, _) = started();
        stop_listing(
            &mut core,
            reviewer,
            5_000,
            StopPending {
                tasks: vec!["shell".into()],
                wakeups: vec![],
            },
        );
        core.dispatch(AppAction::HostListed(vec![]), Clock::at(6_000));
        assert!(!core.is_running(reviewer));
        missing(&mut core, run, past_grace(5_000));
        assert!(matches!(run_of(&core).state, RunState::Failed(_)));
    }

    #[test]
    fn a_held_agent_gone_quiet_is_not_stalled_until_the_hold_ends() {
        let (mut core, run, _, reviewer, _) = started();
        stop_listing(&mut core, reviewer, 5_000, wakeup(600_000));
        core.dispatch(
            AppAction::HostListed(vec![HostStatus {
                last_activity: Some(Clock::at(5_000).wall),
                ..running(reviewer)
            }]),
            Clock::at(6_000),
        );
        core.dispatch(AppAction::Tick, Clock::at(300_000));
        assert!(!core.stalled(run));
        assert!(core.notice().is_none());
        assert_eq!(core.card_state(reviewer), CardState::Idle);
        assert!(core.stalled_agents().next().is_none());
        // Once the wakeup and its grace are past, the stall check runs.
        core.dispatch(AppAction::Tick, Clock::at(past_grace(600_000)));
        assert!(core.stalled(run));
        assert!(core.notice().is_some());
        assert_eq!(core.card_state(reviewer), CardState::WaitingOnYou);
    }

    #[test]
    fn a_hold_that_starts_lifts_a_stall_mark() {
        let (mut core, run, _, reviewer, _) = started();
        core.dispatch(
            AppAction::HostListed(vec![HostStatus {
                last_activity: Some(Clock::at(5_000).wall),
                ..running(reviewer)
            }]),
            Clock::at(6_000),
        );
        core.dispatch(AppAction::Tick, Clock::at(200_000));
        assert!(core.stalled(run));
        stop_listing(&mut core, reviewer, 201_000, wakeup(400_000));
        core.dispatch(AppAction::Tick, Clock::at(202_000));
        assert!(!core.stalled(run));
        assert_eq!(core.card_state(reviewer), CardState::Idle);
    }

    #[test]
    fn a_planner_that_stops_without_its_response_fails_the_run() {
