        let reported = core.set_views(SpaceId::DEFAULT);
        assert_eq!(
            reported[0].rule,
            Some(switchboard_control::SetRule::Recent { hours: 24 })
        );
        assert_eq!(reported[0].items.len(), 1);
    }
