    /// The Usage tab asks once per `updated_ms` and never twice at
    /// once; the reply lands on the ticket, and a runner that does not
    /// serve usage marks it unavailable with no notice, until a runner
    /// reconnects.
    #[test]
    fn a_tickets_usage_is_read_once_per_change_and_an_old_runner_is_quiet() {
        let mut core = connected();
        let read = |updated_ms| AppAction::DispatchReadUsage {
            ticket: "t1".into(),
            updated_ms,
        };
        let replied = |result| AppAction::DispatchReplied {
            body: Body::Usage {
                ticket: "t1".into(),
            },
            result,
        };
        assert_eq!(
            core.dispatch(read(50), Clock::at(2)),
            vec![Effect::DispatchCall(Body::Usage {
                ticket: "t1".into()
            })]
        );
        assert!(
            core.dispatch(read(50), Clock::at(3)).is_empty(),
            "in flight"
        );
        assert!(
            core.dispatch(read(51), Clock::at(3)).is_empty(),
            "in flight"
        );
        let view = crate::ports::dispatch::UsageView {
            ticket: "t1".into(),
            not_found: 1,
            ..Default::default()
        };
        core.dispatch(replied(Ok(Reply::Usage(view.clone()))), Clock::at(4));
        assert_eq!(core.dispatch_state().usage["t1"].view, Some(view.clone()));
        assert!(
            core.dispatch(read(50), Clock::at(5)).is_empty(),
            "asked at 50"
        );
        assert_eq!(core.dispatch(read(51), Clock::at(6)).len(), 1);
        core.dispatch(
            replied(Ok(Reply::failed("bad request: unknown variant `usage`"))),
            Clock::at(7),
        );
        assert!(core.notices().is_empty(), "{:?}", core.notices());
        let u = &core.dispatch_state().usage["t1"];
        assert!(u.unavailable);
        assert_eq!(u.view, Some(view), "the last view is kept");
        assert!(core.dispatch(read(52), Clock::at(8)).is_empty());
        core.dispatch(AppAction::DispatchStatus(None), Clock::at(9));
        core.dispatch(AppAction::DispatchStatus(Some(status(None))), Clock::at(10));
        assert_eq!(core.dispatch(read(52), Clock::at(11)).len(), 1);
    }

    /// A runner that reports usage but cannot read this ticket's says
    /// why, without a notice, and is asked again once the ticket
    /// changes; a read that works clears the reason.
    #[test]
    fn a_usage_read_that_fails_keeps_its_reason_and_asks_again_on_a_change() {
        let mut core = connected();
        let read = |updated_ms| AppAction::DispatchReadUsage {
            ticket: "t1".into(),
            updated_ms,
        };
        let replied = |result| AppAction::DispatchReplied {
            body: Body::Usage {
                ticket: "t1".into(),
            },
            result,
        };
        assert_eq!(core.dispatch(read(50), Clock::at(2)).len(), 1);
        core.dispatch(
            replied(Ok(Reply::failed("usage.json is version 9, newer"))),
            Clock::at(3),
        );
        assert!(core.notices().is_empty(), "{:?}", core.notices());
        let u = &core.dispatch_state().usage["t1"];
        assert!(!u.unavailable);
        assert_eq!(u.failed.as_deref(), Some("usage.json is version 9, newer"));
        assert!(
            core.dispatch(read(50), Clock::at(4)).is_empty(),
            "asked at 50"
        );
        assert_eq!(core.dispatch(read(51), Clock::at(5)).len(), 1);
        core.dispatch(
            replied(Ok(Reply::Usage(
                crate::ports::dispatch::UsageView::default(),
            ))),
            Clock::at(6),
        );
        assert_eq!(core.dispatch_state().usage["t1"].failed, None);
    }

    /// The timeline is the event log's, newest first in stage groups,
    /// with an attempt's duration joined from the record; without
    /// events it is made from the record's attempts, decisions and
    /// restarts.
    #[test]
    fn a_tickets_timeline_reads_the_log_else_the_record() {
        let mut core = connected();
        let mut t = status(None).tickets.remove(0);
        t.attempts[0].started_ms = 1_000;
        t.attempts[0].ended_ms = Some(4_000);
        t.decisions[0].made_ms = 5_000;
        t.decisions.push(DecisionView {
            id: "d0".into(),
            ticket: "t1".into(),
            stage: "investigate".into(),
            name: "rerun".into(),
            question: "Run it again?".into(),
            state: "acted".into(),
            answer: Some("no".into()),
            answered_by: Some("user".into()),
            answered_ms: Some(4_500),
            made_ms: 4_200,
            ..DecisionView::default()
        });
        t.restarts.push(dispatch_control::RestartView {
            at_ms: 6_000,
            from: "lanes".into(),
            to: "lanes".into(),
            ..Default::default()
        });
        let shape = |groups: Vec<crate::core::dispatch::TimelineGroup>| {
            groups
                .into_iter()
                .map(|g| {
                    (
                        g.stage,
                        g.rows
                            .into_iter()
                            .map(|r| (r.kind, r.duration_ms))
                            .collect::<Vec<_>>(),
                    )
                })
                .collect::<Vec<_>>()
        };
        let s = |x: &str| x.to_owned();
        assert_eq!(
            shape(core.ticket_timeline(&t).groups),
            vec![
                (
                    s("lanes"),
                    vec![(s("restarted"), None), (s("decision"), None)]
                ),
                (
                    s("investigate"),
                    vec![
                        (s("answered"), None),
                        (s("decision"), None),
                        (s("attempt-ended"), Some(3_000)),
                        (s("attempt-started"), None),
                    ]
                ),
            ]
        );
        let answered = &core.ticket_timeline(&t).groups[1].rows[0];
        assert_eq!(answered.text, "rerun by user: no");
        assert_eq!(answered.decision.as_deref(), Some("d0"));
        core.dispatch(read_events(50), Clock::at(2));
        let mut ended = logged(2, "investigate", "attempt-ended", "investigate/1 complete");
        ended.attempt = Some(("investigate".into(), 1));
        core.dispatch(
            events_replied(
                0,
                Reply::Events(EventsView {
                    events: vec![
                        logged(1, "investigate", "attempt-started", "started"),
                        ended,
                        logged(3, "lanes", "stage", "to lanes"),
                        logged(4, "lanes", "decision", "Which lanes?"),
                    ],
                    last: 4,
                    withdrawn: Vec::new(),
                }),
            ),
            Clock::at(3),
        );
        assert_eq!(
            shape(core.ticket_timeline(&t).groups),
            vec![
                (s("lanes"), vec![(s("decision"), None), (s("stage"), None)]),
                (
                    s("investigate"),
                    vec![
                        (s("attempt-ended"), Some(3_000)),
                        (s("attempt-started"), None)
                    ]
                ),
            ]
        );
    }

    /// A ticket in progress when the log began keeps its record's
    /// earlier history: rows before the first event are merged in, less
    /// those the log has for the same attempt or decision.
    #[test]
    fn a_timeline_keeps_the_records_rows_from_before_the_log() {
        let mut core = connected();
        let mut t = status(None).tickets.remove(0);
        t.attempts[0].started_ms = 500;
        t.attempts[0].ended_ms = Some(2_900);
        t.decisions[0].made_ms = 4_500;
        t.decisions.push(DecisionView {
            id: "d0".into(),
            ticket: "t1".into(),
            stage: "investigate".into(),
            name: "rerun".into(),
            question: "Run it again?".into(),
            state: "acted".into(),
            answer: Some("yes".into()),
            answered_by: Some("user".into()),
            answered_ms: Some(700),
            made_ms: 600,
            ..DecisionView::default()
        });
        core.dispatch(read_events(50), Clock::at(2));
        let mut ended = logged(3, "investigate", "attempt-ended", "investigate/1 complete");
        ended.attempt = Some(("investigate".into(), 1));
        core.dispatch(
            events_replied(
                0,
                Reply::Events(EventsView {
                    events: vec![ended, logged(4, "lanes", "stage", "to lanes")],
                    last: 4,
                    withdrawn: Vec::new(),
                }),
            ),
            Clock::at(3),
        );
        let rows: Vec<(String, u64)> = core
            .ticket_timeline(&t)
            .groups
            .into_iter()
            .flat_map(|g| g.rows)
            .map(|r| (r.kind, r.at_ms))
            .collect();
        let s = |x: &str| x.to_owned();
        assert_eq!(
            rows,
            vec![
                (s("stage"), 4_000),
                // The record's end at 2 900 is the log's at 3 000.
                (s("attempt-ended"), 3_000),
                (s("answered"), 700),
                (s("decision"), 600),
                (s("attempt-started"), 500),
            ]
        );
    }

    /// Each attempt's card goes under its newest end row, else its start
    /// row while it runs; attempts no row carries are the earlier ones.
    #[test]
    fn a_timeline_places_each_attempts_card_once() {
        let mut core = connected();
        let mut t = status(None).tickets.remove(0);
        t.attempts[0].started_ms = 1_000;
        t.attempts[0].ended_ms = Some(2_000);
        t.decisions[0].made_ms = 3_500;
        t.attempts.push(AttemptView {
            stage: "lanes".into(),
            n: 1,
            state: "running".into(),
            ..AttemptView::default()
        });
        t.attempts.push(AttemptView {
            stage: "lanes".into(),
            n: 2,
            state: "running".into(),
            started_ms: 3_500,
            ..AttemptView::default()
        });
        core.dispatch(read_events(50), Clock::at(2));
        let of = |seq, kind: &str, stage: &str, n| {
            let mut e = logged(seq, stage, kind, "");
            e.attempt = Some((stage.to_owned(), n));
            e
        };
        core.dispatch(
            events_replied(
                0,
                Reply::Events(EventsView {
                    events: vec![
                        of(1, "attempt-started", "investigate", 1),
                        of(2, "attempt-ended", "investigate", 1),
                        of(3, "attempt-started", "lanes", 1),
                    ],
                    last: 3,
                    withdrawn: Vec::new(),
                }),
            ),
            Clock::at(3),
        );
        let timeline = core.ticket_timeline(&t);
        let carried: Vec<(String, Option<(String, u32)>)> = timeline
            .groups
            .into_iter()
            .flat_map(|g| g.rows)
            .map(|r| (r.kind, r.details))
            .collect();
        let s = |x: &str| x.to_owned();
        assert_eq!(
            carried,
            vec![
                (s("attempt-started"), Some((s("lanes"), 1))),
                (s("attempt-ended"), Some((s("investigate"), 1))),
                (s("attempt-started"), None),
            ]
        );
        assert_eq!(timeline.earlier, vec![(s("lanes"), 2)]);
    }

    /// A failed artifact read is said on the page, not as a notice, and
    /// asked again once the ticket changes or on a click; a call that
    /// never reached the runner is asked again when it is back.
    #[test]
    fn a_failed_artifact_read_is_asked_again_when_the_ticket_changes() {
        let mut core = connected();
        let path = std::path::PathBuf::from("/dispatch/t1/notes.md");
        let read = AppAction::DispatchReadArtifact {
            ticket: "t1".into(),
            path: path.clone(),
        };
        let replied = |result| AppAction::DispatchReplied {
            body: Body::Artifact {
                ticket: "t1".into(),
                path: path.clone(),
            },
            result,
        };
        let t = |updated_ms| TicketView {
            updated_ms,
            ..status(None).tickets.remove(0)
        };
        assert!(core.artifact_read_due(&t(0), &path));
        assert_eq!(core.dispatch(read.clone(), Clock::at(2)).len(), 1);
        assert!(!core.artifact_read_due(&t(0), &path), "in flight");
        assert!(core.dispatch(read.clone(), Clock::at(3)).is_empty());
        core.dispatch(
            replied(Ok(Reply::failed(
                "read /dispatch/t1/notes.md: No such file or directory (os error 2)",
            ))),
            Clock::at(4),
        );
        assert!(core.notices().is_empty(), "{:?}", core.notices());
        assert!(core.artifact_read(&path).is_some_and(ArtifactRead::missing));
        assert!(!core.artifact_read_due(&t(0), &path), "asked at 0");
        assert!(core.artifact_read_due(&t(10), &path), "the ticket changed");
        assert_eq!(
            core.dispatch(read.clone(), Clock::at(5)).len(),
            1,
            "a click"
        );
        core.dispatch(replied(Err("connection reset".into())), Clock::at(6));
        core.dispatch(AppAction::DispatchStatus(Some(status(None))), Clock::at(7));
        assert!(
            core.artifact_read_due(&t(0), &path),
            "never reached the runner"
        );
        core.dispatch(read, Clock::at(8));
        core.dispatch(
            replied(Ok(Reply::Artifact {
                text: "# notes".into(),
            })),
            Clock::at(9),
        );
        assert!(core.artifact_read(&path).is_none());
        assert!(!core.artifact_read_due(&t(0), &path), "read at 0");
        assert!(
            core.artifact_read_due(&t(10), &path),
            "the ticket moved past the read"
        );
    }

    /// A review edits its copy in place under one path, so text already
    /// read is read again once the ticket moves; the old text stays until
    /// a reply brings new text, and a failed re-read leaves it.
    #[test]
    fn an_artifact_read_again_replaces_its_text_and_a_failure_keeps_it() {
        let mut core = connected();
        let path = std::path::PathBuf::from("/dispatch/t1/review/1/plan.md");
        let read = AppAction::DispatchReadArtifact {
            ticket: "t1".into(),
            path: path.clone(),
        };
        let replied = |result| AppAction::DispatchReplied {
            body: Body::Artifact {
                ticket: "t1".into(),
                path: path.clone(),
            },
            result,
        };
        let moved = |updated_ms| {
            let mut s = status(None);
            s.tickets[0].updated_ms = updated_ms;
            AppAction::DispatchStatus(Some(s))
        };
        let text = |core: &AppCore| core.dispatch_state().artifacts.get(&path).cloned();
        core.dispatch(moved(5), Clock::at(1));
        core.dispatch(read.clone(), Clock::at(2));
        core.dispatch(
            replied(Ok(Reply::Artifact { text: "v1".into() })),
            Clock::at(3),
        );
        assert_eq!(text(&core).as_deref(), Some("v1"));
        assert!(
            core.dispatch(read.clone(), Clock::at(4)).is_empty(),
            "current"
        );

        core.dispatch(moved(10), Clock::at(5));
        let t = core.ticket("t1").unwrap().clone();
        assert!(core.artifact_read_due(&t, &path));
        assert_eq!(core.dispatch(read.clone(), Clock::at(6)).len(), 1);
        assert_eq!(text(&core).as_deref(), Some("v1"), "drawn while read again");
        core.dispatch(
            replied(Ok(Reply::Artifact { text: "v2".into() })),
            Clock::at(7),
        );
        assert_eq!(text(&core).as_deref(), Some("v2"));
        assert!(!core.artifact_read_due(&t, &path));

        core.dispatch(moved(20), Clock::at(8));
        let t = core.ticket("t1").unwrap().clone();
        core.dispatch(read.clone(), Clock::at(9));
        core.dispatch(replied(Ok(Reply::failed("read: busy"))), Clock::at(10));
        assert_eq!(text(&core).as_deref(), Some("v2"), "kept");
        assert_eq!(
            core.artifact_read(&path).and_then(|r| r.failed.as_deref()),
            Some("read: busy")
        );
        assert!(!core.artifact_read_due(&t, &path), "asked at 20 already");
        assert_eq!(core.dispatch(read, Clock::at(11)).len(), 1, "a click");
    }

