// --- environment sets: resolution, the setup window, grants and tokens

mod env_sets {
    use super::*;
    use crate::core::env::{SecretScope, resolve_sets};
    use crate::core::{
        AwsMethod, ControlAction, ENV_SETUP_LOCKED, ENV_SETUP_WINDOW, EnvSet, EnvVar, GrantTarget,
    };

    fn var(name: &str, value: &str, secret: bool) -> EnvVar {
        EnvVar {
            name: name.into(),
            value: value.into(),
            secret,
        }
    }

    fn set(name: &str, vars: Vec<EnvVar>, aws: Option<AwsMethod>) -> EnvSet {
        EnvSet {
            name: name.into(),
            vars,
            aws,
        }
    }

    fn control(core: &mut AppCore, op: &str, action: ControlAction, at: u64) -> Vec<Effect> {
        core.dispatch(
            AppAction::Control {
                op: op.into(),
                action,
            },
            Clock::at(at),
        )
    }

    fn upsert(name: &str, vars: Vec<EnvVar>, aws: Option<AwsMethod>) -> ControlAction {
        ControlAction::EnvSetUpsert {
            name: name.into(),
            vars,
            aws,
        }
    }

    fn grant(target: GrantTarget, set: &str, remove: bool) -> ControlAction {
        ControlAction::EnvGrant {
            target,
            set: set.into(),
            remove,
        }
    }

    /// The error a control command ended with, if any.
    fn refusal(core: &mut AppCore, op: &str) -> Option<String> {
        core.take_control_outcome(op).and_then(|o| o.error)
    }

    /// A core with one shell record and the given sets, the Dispatch
    /// runner being that record when `runner` is set.
    fn with_sets(sets: Vec<EnvSet>, runner: bool) -> (AppCore, ProjectId, RecordId) {
        let p = project("p");
        let pid = p.id;
        let mut w = Workspace::new(p);
        let r = record(pid, SessionKind::Service, 0);
        let id = r.id;
        w.sessions.push(r);
        let mut core = AppCore::new();
        core.dispatch(
            AppAction::StoreLoaded(Ok(Loaded {
                workspaces: vec![w],
                settings: Settings {
                    env_sets: sets,
                    dispatch_runner: runner.then_some(id),
                    ..Settings::default()
                },
                ..Loaded::default()
            })),
            Clock::at(0),
        );
        core.dispatch(AppAction::HostListed(vec![]), Clock::at(1));
        (core, pid, id)
    }

    #[test]
    fn a_sessions_set_wins_over_its_projects_and_missing_secrets_are_named() {
        let sets = vec![
            set("base", vec![var("REGION", "us-east-1", false)], None),
            set(
                "dev",
                vec![var("REGION", "eu-west-1", false), var("TOKEN", "", true)],
                None,
            ),
            set("ci", vec![var("KEY", "", true)], None),
        ];
        let lookup = |account: &str| (account == "set/dev/TOKEN").then(|| "t0k".to_owned());
        let r = resolve_sets(
            &sets,
            &["base".into(), "ci".into()],
            &["dev".into(), "base".into()],
            &lookup,
        )
        .unwrap();
        assert_eq!(
            r.pairs,
            vec![
                ("REGION".to_owned(), "eu-west-1".to_owned()),
                ("TOKEN".to_owned(), "t0k".to_owned())
            ]
        );
        assert_eq!(r.missing, vec!["ci/KEY".to_owned()]);
        assert_eq!(r.aws, None);
    }

    #[test]
    fn a_later_sets_value_clears_an_earlier_sets_missing_secret() {
        let sets = vec![
            set("a", vec![var("TOKEN", "", true)], None),
            set("b", vec![var("TOKEN", "x", false)], None),
        ];
        let none = |_: &str| None;
        let r = resolve_sets(&sets, &["a".into()], &["b".into()], &none).unwrap();
        assert_eq!(r.pairs, vec![("TOKEN".to_owned(), "x".to_owned())]);
        assert!(r.missing.is_empty(), "{:?}", r.missing);
    }

    #[test]
    fn an_unknown_set_and_two_aws_methods_are_errors_naming_them() {
        let vault = |p: &str| Some(AwsMethod::Vault { profile: p.into() });
        let sets = vec![
            set("a", vec![], vault("one")),
            set("b", vec![], vault("two")),
        ];
        let none = |_: &str| None;
        let err = resolve_sets(&sets, &[], &["gone".into()], &none).unwrap_err();
        assert!(err.contains("gone"), "{err}");
        let err = resolve_sets(&sets, &["a".into()], &["b".into()], &none).unwrap_err();
        assert!(err.contains('a') && err.contains('b'), "{err}");
        let one = resolve_sets(&sets, &["a".into()], &["a".into()], &none).unwrap();
        assert_eq!(one.aws, vault("one"));
    }

    #[test]
    fn a_set_secret_lives_under_its_own_account() {
        assert_eq!(
            SecretScope::Set("aws-dev".into()).account("TOKEN"),
            "set/aws-dev/TOKEN"
        );
        assert!(crate::core::env::valid_set_name("aws-dev2"));
        assert!(!crate::core::env::valid_set_name("a/b"));
        assert!(!crate::core::env::valid_set_name("-x"));
        assert!(!crate::core::env::valid_set_name("Dev"));
        assert!(crate::core::env::valid_var_name("_AWS_REGION2"));
        assert!(!crate::core::env::valid_var_name("2X"));
        assert!(!crate::core::env::valid_var_name("lower"));
    }

    /// Every write is refused until the owner opens the window, accepted
    /// inside it, and refused once it has passed; the window is never
    /// saved, and a `Tick` past it closes it.
    #[test]
    fn the_setup_commands_are_accepted_only_inside_the_window() {
        let (mut core, pid, id) = with_sets(vec![set("dev", vec![], None)], false);
        let writes = || {
            vec![
                upsert("dev", vec![var("A", "1", false)], None),
                ControlAction::EnvSecretStore {
                    set: "dev".into(),
                    name: "TOKEN".into(),
                    value: "v".into(),
                },
                grant(GrantTarget::Session(id), "dev", false),
            ]
        };
        for (n, action) in writes().into_iter().enumerate() {
            let op = format!("locked-{n}");
            let e = control(&mut core, &op, action, 10);
            assert_eq!(refusal(&mut core, &op).as_deref(), Some(ENV_SETUP_LOCKED));
            assert!(e.is_empty(), "{e:?}");
        }
        let e = core.dispatch(AppAction::SetEnvSetup { open: true }, Clock::at(1_000));
        assert!(e.is_empty(), "the window is never saved: {e:?}");
        assert!(core.env_setup_until().is_some());
        for (n, action) in writes().into_iter().enumerate() {
            let op = format!("open-{n}");
            control(&mut core, &op, action, 2_000);
            assert_eq!(refusal(&mut core, &op), None);
        }
        assert_eq!(core.session(id).unwrap().env_sets, vec!["dev".to_owned()]);
        let past = 1_000 + u64::try_from(ENV_SETUP_WINDOW.as_millis()).unwrap();
        control(
            &mut core,
            "late",
            grant(GrantTarget::Project(pid), "dev", false),
            past,
        );
        assert_eq!(
            refusal(&mut core, "late").as_deref(),
            Some(ENV_SETUP_LOCKED)
        );
        let e = core.dispatch(AppAction::Tick, Clock::at(past));
        assert!(core.env_setup_until().is_none());
        assert!(!e.iter().any(|e| matches!(e, Effect::SaveSettings(_))));
        // Closing by hand works too.
        core.dispatch(AppAction::SetEnvSetup { open: true }, Clock::at(past));
        core.dispatch(AppAction::SetEnvSetup { open: false }, Clock::at(past));
        assert!(core.env_setup_until().is_none());
    }

    fn unlocked(sets: Vec<EnvSet>, runner: bool) -> (AppCore, ProjectId, RecordId) {
        let (mut core, pid, id) = with_sets(sets, runner);
        core.dispatch(AppAction::SetEnvSetup { open: true }, Clock::at(5));
        (core, pid, id)
    }

    fn saved_sets(effects: &[Effect]) -> Option<Vec<EnvSet>> {
        effects.iter().find_map(|e| match e {
            Effect::SaveSettings(s) => Some(s.env_sets.clone()),
            _ => None,
        })
    }

    #[test]
    fn upsert_creates_a_set_merges_variables_and_never_stores_a_secret_value() {
        let (mut core, _, _) = unlocked(vec![], false);
        control(
            &mut core,
            "u1",
            upsert(
                "dev",
                vec![var("A", "1", false), var("B", "2", false)],
                Some(AwsMethod::Sso {
                    profile: "p".into(),
                }),
            ),
            10,
        );
        assert_eq!(refusal(&mut core, "u1"), None);
        // A second upsert replaces one variable and keeps the method.
        let e = control(
            &mut core,
            "u2",
            upsert("dev", vec![var("A", "9", false)], None),
            11,
        );
        let sets = saved_sets(&e).expect("settings saved");
        assert_eq!(
            sets,
            vec![set(
                "dev",
                vec![var("A", "9", false), var("B", "2", false)],
                Some(AwsMethod::Sso {
                    profile: "p".into()
                })
            )]
        );
        // A secret's value never travels in an upsert.
        let e = control(
            &mut core,
            "u3",
            upsert("dev", vec![var("C", "leak", true)], None),
            12,
        );
        assert!(
            refusal(&mut core, "u3")
                .unwrap()
                .contains("env.secret.store")
        );
        assert!(saved_sets(&e).is_none());
        // Turning a plain variable secret blanks what settings held.
        let e = control(
            &mut core,
            "u4",
            upsert("dev", vec![var("B", "", true)], None),
            13,
        );
        let sets = saved_sets(&e).unwrap();
        assert_eq!(sets[0].vars[1], var("B", "", true));
        assert!(!format!("{sets:?}").contains("\"2\""));
        // Bad names change nothing.
        for (op, action) in [
            ("bad-set", upsert("a/b", vec![], None)),
            (
                "bad-var",
                upsert("dev", vec![var("lower", "x", false)], None),
            ),
        ] {
            let e = control(&mut core, op, action, 14);
            assert!(refusal(&mut core, op).is_some(), "{op}");
            assert!(saved_sets(&e).is_none(), "{op}");
        }
    }

    #[test]
    fn a_secret_store_adds_the_variable_and_stores_the_value_under_the_set() {
        let (mut core, _, _) =
            unlocked(vec![set("dev", vec![var("T", "old", false)], None)], false);
        let e = control(
            &mut core,
            "s1",
            ControlAction::EnvSecretStore {
                set: "dev".into(),
                name: "T".into(),
                value: "s3cret".into(),
            },
            10,
        );
        assert_eq!(refusal(&mut core, "s1"), None);
        assert!(e.contains(&Effect::StoreSecret {
            account: "set/dev/T".into(),
            value: "s3cret".into(),
        }));
        let sets = saved_sets(&e).expect("the variable is marked secret");
        assert_eq!(sets[0].vars, vec![var("T", "", true)]);
        assert!(!format!("{:?}", core.settings()).contains("s3cret"));
        control(
            &mut core,
            "s2",
            ControlAction::EnvSecretStore {
                set: "nope".into(),
                name: "T".into(),
                value: "x".into(),
            },
            11,
        );
        assert!(refusal(&mut core, "s2").unwrap().contains("nope"));
    }

    #[test]
    fn grants_and_revokes_edit_the_target_and_refuse_what_cannot_be_granted() {
        let (mut core, pid, id) = unlocked(vec![set("dev", vec![], None)], true);
        let e = control(
            &mut core,
            "g1",
            grant(GrantTarget::Project(pid), "dev", false),
            10,
        );
        assert_eq!(refusal(&mut core, "g1"), None);
        assert_eq!(saves(&e), 1);
        assert_eq!(core.workspace(pid).unwrap().project.env_sets, ["dev"]);
        control(
            &mut core,
            "g2",
            grant(GrantTarget::Runner, "dev", false),
            11,
        );
        control(
            &mut core,
            "g3",
            grant(GrantTarget::Runner, "dev", false),
            12,
        );
        assert_eq!(core.session(id).unwrap().env_sets, ["dev"], "no repeats");
        let e = control(&mut core, "r1", grant(GrantTarget::Runner, "dev", true), 13);
        assert_eq!(saves(&e), 1);
        assert!(core.session(id).unwrap().env_sets.is_empty());
        control(
            &mut core,
            "r2",
            grant(GrantTarget::Project(pid), "dev", true),
            14,
        );
        assert!(core.workspace(pid).unwrap().project.env_sets.is_empty());
        for (op, action) in [
            ("unknown", grant(GrantTarget::Session(id), "gone", false)),
            ("bad", grant(GrantTarget::Session(id), "A/B", false)),
            (
                "nobody",
                grant(GrantTarget::Session(RecordId::new()), "dev", false),
            ),
        ] {
            let e = control(&mut core, op, action, 15);
            assert!(refusal(&mut core, op).is_some(), "{op}");
            assert_eq!(saves(&e), 0, "{op}");
        }
        let (mut core, _, _) = unlocked(vec![set("dev", vec![], None)], false);
        control(
            &mut core,
            "nr",
            grant(GrantTarget::Runner, "dev", false),
            10,
        );
        assert!(refusal(&mut core, "nr").unwrap().contains("runner"));
    }

    #[test]
    fn a_launch_token_hash_lands_on_the_record_and_is_saved() {
        let (mut core, _, id) = with_sets(vec![], false);
        let e = core.dispatch(
            AppAction::RecordTokenIssued {
                id,
                hash: "abc".into(),
            },
            Clock::at(10),
        );
        assert_eq!(saves(&e), 1);
        assert_eq!(core.session(id).unwrap().token_hash.as_deref(), Some("abc"));
        assert_eq!(
            crate::core::token_hash("t"),
            "e3b98a4da31a127d4bde6e43033f66ba274cab0eb7eb1c70ec41402bf6273dd8"
        );
    }

    #[test]
    fn a_port_session_keeps_its_sets_and_a_port_clone_takes_only_the_asked_ones() {
        let p = project("p");
        let pid = p.id;
        let mut w = Workspace::new(p);
        let mut r = record(pid, agent(), 0);
        r.resume = Some(claude_handle());
        r.env_sets = vec!["impl".into()];
        r.token_hash = Some("h".into());
        let source = r.id;
        w.sessions.push(r);
        let (mut core, _) = loaded(vec![w], vec![]);
        control(
            &mut core,
            "n1",
            ControlAction::NewSession {
                project: pid,
                name: "tester".into(),
                kind: agent(),
                cwd: "/tmp/proj".into(),
                launch: Launch::Shell,
                prompt: None,
                notes: String::new(),
                env: BTreeMap::new(),
                env_sets: vec!["aws-dev".into()],
                replaces: None,
            },
            10,
        );
        let by_name = |core: &AppCore, n: &str| {
            core.workspace(pid)
                .unwrap()
                .sessions
                .iter()
                .find(|s| s.name == n)
                .cloned()
                .unwrap()
        };
        assert_eq!(by_name(&core, "tester").env_sets, ["aws-dev"]);
        for (op, name, sets) in [
            ("c1", "fixer", vec!["ci".to_owned()]),
            ("c2", "rebaser", vec![]),
        ] {
            control(
                &mut core,
                op,
                ControlAction::CloneSession {
                    source,
                    name: name.into(),
                    prompt: "go".into(),
                    notes: String::new(),
                    env_sets: sets.clone(),
                },
                11,
            );
            let clone = by_name(&core, name);
            assert_eq!(clone.env_sets, sets, "{name}");
            assert_eq!(clone.token_hash, None, "{name}");
        }
    }

    /// The user's own clone continues the same conversation under the
    /// same launch, so it keeps the source's grants, as it keeps `env`.
    #[test]
    fn the_users_clone_keeps_the_sources_sets_but_not_its_token() {
        let (mut core, id) = resumable_agent();
        let pid = core.session(id).unwrap().project;
        core.edit_session(id, &mut crate::core::action::Out::default(), |s| {
            s.env_sets = vec!["dev".into()];
            s.token_hash = Some("h".into());
        });
        core.dispatch(
            AppAction::CloneSession {
                id,
                before: usize::MAX,
                prompt: String::new(),
            },
            Clock::at(1),
        );
        core.dispatch(
            AppAction::TranscriptCloned {
                source: id,
                prompt: String::new(),
                result: Ok(claude_handle()),
            },
            Clock::at(2),
        );
        let clone = core
            .workspace(pid)
            .unwrap()
            .sessions
            .iter()
            .find(|s| s.id != id)
            .cloned()
            .unwrap();
        assert_eq!(clone.env_sets, ["dev"]);
        assert_eq!(clone.token_hash, None);
    }
}

mod asking {
    use super::*;
    use crate::core::control::ask_message;
    use crate::core::{ASK_MAX_CHARS, Ask, ControlAction, token_hash};

    fn control(core: &mut AppCore, op: &str, action: ControlAction, at: u64) -> Vec<Effect> {
        core.dispatch(
            AppAction::Control {
                op: op.into(),
                action,
            },
            Clock::at(at),
        )
    }

    fn ask(id: RecordId, token: &str, message: Option<&str>) -> ControlAction {
        ControlAction::Ask {
            id,
            token: token.into(),
            message: message.map(str::to_owned),
            kind: None,
            choices: vec![],
        }
    }

    /// A running agent whose latest spawn was given the token "t".
    fn with_token() -> (AppCore, RecordId) {
        let p = project("p");
        let mut w = Workspace::new(p.clone());
        let mut r = record(p.id, agent(), 0);
        r.token_hash = Some(token_hash("t"));
        let id = r.id;
        w.sessions.push(r);
        let (mut core, _) = loaded(vec![w], vec![]);
        core.dispatch(AppAction::HostListed(vec![running(id)]), Clock::at(1));
        (core, id)
    }

    fn an_ask() -> Ask {
        Ask::note("merge?", Clock::at(1).wall)
    }

    #[test]
    fn dispatch_waiting_off_leaves_a_sessions_own_ask() {
        let (mut core, id) = with_token();
        control(&mut core, "a", ask(id, "t", Some("merge?")), 2);
        control(
            &mut core,
            "w",
            ControlAction::SetWaiting {
                id,
                reason: Some("finalize?".into()),
            },
            3,
        );
        control(
            &mut core,
            "off",
            ControlAction::SetWaiting { id, reason: None },
            4,
        );
        let s = core.session(id).unwrap();
        assert_eq!(
            s.asking.as_ref().map(|a| a.message.as_str()),
            Some("merge?")
        );
        control(
            &mut core,
            "w2",
            ControlAction::SetWaiting {
                id,
                reason: Some("finalize?".into()),
            },
            5,
        );
        control(&mut core, "clear", ask(id, "t", None), 6);
        let s = core.session(id).unwrap();
        assert_eq!(s.asking, None);
        assert_eq!(s.waiting_on.as_deref(), Some("finalize?"));
    }

    #[test]
    fn an_ask_with_a_wrong_or_missing_token_is_refused() {
        let (mut core, id) = with_token();
        let before = core.session(id).unwrap().clone();
        let cases = [
            ("wrong", ask(id, "nope", Some("x")), "token does not match"),
            ("empty", ask(id, "", Some("x")), "token does not match"),
            ("blank", ask(id, "t", Some(" \n")), "an ask needs a message"),
            (
                "unknown",
                ask(RecordId::new(), "t", Some("x")),
                "no such session",
            ),
        ];
        for (op, action, why) in cases {
            let e = control(&mut core, op, action, 2);
            assert_eq!(saves(&e), 0, "{op}");
            assert_eq!(
                core.take_control_outcome(op).unwrap().error.as_deref(),
                Some(why),
                "{op}"
            );
        }
        assert_eq!(core.session(id).unwrap(), &before);
        // A record from before tokens cannot be asked for at all.
        let p = project("old");
        let mut w = Workspace::new(p.clone());
        let r = record(p.id, agent(), 0);
        let old = r.id;
        w.sessions.push(r);
        let (mut core, _) = loaded(vec![w], vec![]);
        let e = control(&mut core, "old", ask(old, "t", Some("x")), 2);
        assert_eq!(saves(&e), 0);
        assert_eq!(
            core.take_control_outcome("old").unwrap().error.as_deref(),
            Some("this session was launched before tokens; restart it")
        );
        assert_eq!(core.session(old).unwrap().asking, None);
    }

    #[test]
    fn an_ask_clears_on_dismiss_and_on_a_new_spawn() {
        let (mut core, id) = with_token();
        core.seed_asking(id, Some(an_ask()));
        let e = core.dispatch(AppAction::DismissAsk(id), Clock::at(2));
        assert_eq!(saves(&e), 1);
        assert_eq!(core.session(id).unwrap().asking, None);
        assert_ne!(core.card_state(id), CardState::WaitingOnYou);

        let (mut core, pid, _) = with_records(&[], |_| None);
        let (id, _) = new_session(&mut core, pid, agent(), Launch::Argv(vec![]));
        core.seed_asking(id, Some(an_ask()));
        launch_agent(&mut core, id, Some(claude_handle()));
        assert_eq!(
            core.session(id).unwrap().asking,
            None,
            "a new process has asked nothing"
        );
    }

    #[test]
    fn a_clone_starts_with_no_ask() {
        let (mut core, id) = resumable_agent();
        core.seed_asking(id, Some(an_ask()));
        core.dispatch(
            AppAction::CloneSession {
                id,
                before: 1,
                prompt: "p".into(),
            },
            Clock::at(1),
        );
        core.dispatch(
            AppAction::TranscriptCloned {
                source: id,
                prompt: "p".into(),
                result: Ok(ResumeHandle::ClaudeCode {
                    session_id: Uuid::new_v4(),
                    transcript: Some(PathBuf::from("/tmp/forked.jsonl")),
                }),
            },
            Clock::at(2),
        );
        let project = core.session(id).unwrap().project;
        let clone = core
            .workspace(project)
            .unwrap()
            .sessions
            .iter()
            .find(|s| s.id != id)
            .unwrap();
        assert_eq!(clone.asking, None);
    }

    #[test]
    fn ask_message_keeps_one_capped_line() {
        assert_eq!(
            ask_message("  merge now?  \nmore detail").as_deref(),
            Some("merge now?")
        );
        let long = "é".repeat(ASK_MAX_CHARS + 10);
        let kept = ask_message(&long).unwrap();
        assert_eq!(kept.chars().count(), ASK_MAX_CHARS + 1);
        assert!(kept.ends_with('…'));
        assert_eq!(
            ask_message(&"a".repeat(ASK_MAX_CHARS)).unwrap().len(),
            ASK_MAX_CHARS
        );
        assert_eq!(ask_message("   "), None);
        assert_eq!(ask_message(""), None);
    }
}

mod answering {
    use std::time::SystemTime;

    use super::*;
    use crate::core::{Ask, AskKind, ControlAction, token_hash};

    fn sends(effects: &[Effect]) -> Vec<&str> {
        effects
            .iter()
            .filter_map(|e| match e {
                Effect::SendAnswer { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect()
    }

    fn hook(core: &mut AppCore, id: RecordId, kind: EventKind, at: u64) -> Vec<Effect> {
        core.dispatch(
            AppAction::Events(vec![SessionEvent {
                record_id: Some(id),
                ..event(kind, at)
            }]),
            Clock::at(at + 1),
        )
    }

    fn stopped() -> EventKind {
        EventKind::Stopped {
            last_message: None,
            pending: None,
        }
    }

    fn ask_op(id: RecordId, kind: Option<&str>, choices: &[&str]) -> ControlAction {
        ControlAction::Ask {
            id,
            token: "t".into(),
            message: Some("pick".into()),
            kind: kind.map(str::to_owned),
            choices: choices.iter().map(|c| (*c).to_owned()).collect(),
        }
    }

    /// Asks over the control port and returns the refusal, if any.
    fn ask(core: &mut AppCore, action: ControlAction, at: u64) -> Option<String> {
        core.dispatch(
            AppAction::Control {
                op: format!("ask{at}"),
                action,
            },
            Clock::at(at),
        );
        core.take_control_outcome(&format!("ask{at}"))
            .unwrap()
            .error
    }

    /// A running session of `kind` with the token "t", at its prompt
    /// after a `Stop` at 2s.
    fn at_prompt(kind: SessionKind) -> (AppCore, RecordId) {
        let p = project("p");
        let mut w = Workspace::new(p.clone());
        let mut r = record(p.id, kind, 0);
        r.token_hash = Some(token_hash("t"));
        let id = r.id;
        w.sessions.push(r);
        let (mut core, _) = loaded(vec![w], vec![]);
        core.dispatch(AppAction::HostListed(vec![running(id)]), Clock::at(1));
        hook(&mut core, id, stopped(), 2_000);
        (core, id)
    }

    /// A Claude Code agent at its prompt that asked "pick" at 3s.
    fn asked(kind: &str, choices: &[&str]) -> (AppCore, RecordId) {
        let (mut core, id) = at_prompt(agent());
        assert_eq!(ask(&mut core, ask_op(id, Some(kind), choices), 3_000), None);
        (core, id)
    }

    fn ask_at(core: &AppCore, id: RecordId) -> SystemTime {
        core.session(id).unwrap().asking.as_ref().unwrap().at
    }

    fn answer(core: &mut AppCore, id: RecordId, text: &str, at: u64) -> Vec<Effect> {
        let asked_at = ask_at(core, id);
        answer_to(core, id, asked_at, text, at)
    }

    fn answer_to(
        core: &mut AppCore,
        id: RecordId,
        asked_at: SystemTime,
        text: &str,
        at: u64,
    ) -> Vec<Effect> {
        core.dispatch(
            AppAction::AnswerAsk {
                id,
                at: asked_at,
                answer: text.into(),
            },
            Clock::at(at),
        )
    }

    fn pending(core: &AppCore, id: RecordId) -> Option<String> {
        core.session(id)?.asking.as_ref()?.answer.clone()
    }

    #[test]
    fn each_kind_answered_between_turns_is_sent_at_once() {
        let cases: [(&str, &[&str], &str, &str); 3] = [
            ("confirm", &[], "yes", "yes"),
            ("choice", &["a", "b"], "b", "b"),
            ("text", &[], "  main, please \nmore", "main, please"),
        ];
        for (kind, choices, given, sent) in cases {
            let (mut core, id) = asked(kind, choices);
            assert!(core.answerable_ask(id).is_some(), "{kind}");
            let e = answer(&mut core, id, given, 4_000);
            assert_eq!(
                sends(&e),
                [format!("Owner answered \"pick\": {sent}").as_str()],
                "{kind}"
            );
            assert_eq!(saves(&e), 1, "{kind}");
            assert_eq!(core.session(id).unwrap().asking, None, "{kind}");
        }
    }

    #[test]
    fn an_answer_given_mid_turn_goes_out_at_the_stop_once() {
        let (mut core, id) = asked("text", &[]);
        hook(&mut core, id, EventKind::ToolFinished, 4_000);
        let e = answer(&mut core, id, "main", 5_000);
        assert!(sends(&e).is_empty());
        assert_eq!(saves(&e), 1);
        assert_eq!(pending(&core, id).as_deref(), Some("main"));
        let e = hook(&mut core, id, stopped(), 6_000);
        assert_eq!(sends(&e), ["Owner answered \"pick\": main"]);
        assert_eq!(core.session(id).unwrap().asking, None);
        let e = hook(&mut core, id, stopped(), 7_000);
        assert!(sends(&e).is_empty());
    }

    #[test]
    fn a_second_answer_before_the_stop_replaces_the_first() {
        let (mut core, id) = asked("confirm", &[]);
        hook(&mut core, id, EventKind::ToolFinished, 4_000);
        answer(&mut core, id, "yes", 5_000);
        answer(&mut core, id, "no", 6_000);
        let e = hook(&mut core, id, stopped(), 7_000);
        assert_eq!(sends(&e), ["Owner answered \"pick\": no"]);
    }

    #[test]
    fn a_click_on_an_answered_or_replaced_ask_is_refused() {
        let (mut core, id) = asked("confirm", &[]);
        let old = ask_at(&core, id);
        hook(&mut core, id, EventKind::PromptSubmitted, 4_000);
        assert_eq!(core.session(id).unwrap().asking, None);
        let e = answer_to(&mut core, id, old, "yes", 5_000);
        assert!(sends(&e).is_empty());
        assert_eq!(saves(&e), 0);
        assert!(
            core.notices()
                .iter()
                .any(|n| n.text.contains("already answered or withdrawn"))
        );

        let (mut core, id) = asked("confirm", &[]);
        let old = ask_at(&core, id);
        assert_eq!(ask(&mut core, ask_op(id, Some("text"), &[]), 4_000), None);
        let e = answer_to(&mut core, id, old, "yes", 5_000);
        assert!(sends(&e).is_empty());
        assert_eq!(saves(&e), 0);
        let s = core.session(id).unwrap().asking.clone().unwrap();
        assert_eq!(s.kind, AskKind::Text);
        assert_eq!(s.answer, None);
    }

    /// A prompt typed inside an open turn is a reminder, not the owner's
    /// reply: the ask and its answer stand until the stop.
    #[test]
    fn a_prompt_inside_the_turn_leaves_the_answer_for_the_stop() {
        let (mut core, id) = asked("confirm", &[]);
        hook(&mut core, id, EventKind::ToolFinished, 4_000);
        answer(&mut core, id, "yes", 5_000);
        hook(&mut core, id, EventKind::PromptSubmitted, 6_000);
        assert_eq!(pending(&core, id).as_deref(), Some("yes"));
        let e = hook(&mut core, id, stopped(), 7_000);
        assert_eq!(sends(&e), ["Owner answered \"pick\": yes"]);
    }

    /// Keys typed at a permission prompt or a failed stop would answer
    /// that instead.
    #[test]
    fn a_dialog_in_the_pane_holds_the_answer() {
        let (mut core, id) = asked("confirm", &[]);
        hook(&mut core, id, EventKind::ToolFinished, 4_000);
        answer(&mut core, id, "yes", 5_000);
        let e = hook(
            &mut core,
            id,
            EventKind::StopFailed {
                reason: Some("rate_limit".into()),
            },
            6_000,
        );
        assert!(sends(&e).is_empty());
        assert_eq!(pending(&core, id).as_deref(), Some("yes"));

        let (mut core, id) = asked("confirm", &[]);
        hook(
            &mut core,
            id,
            EventKind::PermissionRequested {
                tool: Some("Bash".into()),
            },
            4_000,
        );
        let e = answer(&mut core, id, "no", 5_000);
        assert!(sends(&e).is_empty());
        assert_eq!(saves(&e), 1);
        assert_eq!(pending(&core, id).as_deref(), Some("no"));
    }

    /// An MCP tool's dialog closing hands back to the open turn, so
    /// neither the next host list nor a click then sends.
    #[test]
    fn a_closed_mcp_dialog_does_not_end_the_turn() {
        let (mut core, id) = asked("confirm", &[]);
        hook(&mut core, id, EventKind::ToolFinished, 4_000);
        answer(&mut core, id, "yes", 5_000);
        let dialog = |kind: &str| EventKind::Notification { kind: kind.into() };
        hook(&mut core, id, dialog("elicitation_dialog"), 6_000);
        hook(&mut core, id, dialog("elicitation_complete"), 7_000);
        let e = core.dispatch(AppAction::HostListed(vec![running(id)]), Clock::at(8_000));
        assert!(sends(&e).is_empty());
        let e = answer(&mut core, id, "no", 9_000);
        assert!(sends(&e).is_empty());
        assert_eq!(pending(&core, id).as_deref(), Some("no"));
        let e = hook(&mut core, id, stopped(), 10_000);
        assert_eq!(sends(&e), ["Owner answered \"pick\": no"]);
    }

    /// A background agent can finish while the main turn runs on.
    #[test]
    fn a_finished_background_agent_does_not_end_the_turn() {
        let (mut core, id) = asked("confirm", &[]);
        hook(&mut core, id, EventKind::ToolFinished, 4_000);
        answer(&mut core, id, "yes", 5_000);
        let done = EventKind::Notification {
            kind: "agent_completed".into(),
        };
        hook(&mut core, id, done, 6_000);
        let e = core.dispatch(AppAction::HostListed(vec![running(id)]), Clock::at(7_000));
        assert!(sends(&e).is_empty());
        let e = answer(&mut core, id, "no", 8_000);
        assert!(sends(&e).is_empty());
        assert_eq!(pending(&core, id).as_deref(), Some("no"));
        let e = hook(&mut core, id, stopped(), 9_000);
        assert_eq!(sends(&e), ["Owner answered \"pick\": no"]);
    }

    /// The ask stays on the record while the pane is gone, so the
    /// refusal must not say it was answered.
    #[test]
    fn a_click_on_a_stopped_session_says_it_is_not_running() {
        let (mut core, id) = asked("confirm", &[]);
        let at = ask_at(&core, id);
        core.dispatch(AppAction::HostListed(vec![]), Clock::at(4_000));
        let e = answer_to(&mut core, id, at, "yes", 5_000);
        assert!(sends(&e).is_empty());
        assert_eq!(saves(&e), 0);
        assert!(
            core.notices()
                .iter()
                .any(|n| n.text.contains("is not running"))
        );
        assert!(core.session(id).unwrap().asking.is_some());
    }

    /// After a restart the replayed `Stop` lands before the first host
    /// list; that host list sends the answer, once.
    #[test]
    fn an_answer_left_by_a_restart_goes_out_on_the_first_host_list() {
        let p = project("p");
        let mut w = Workspace::new(p.clone());
        let mut r = record(p.id, agent(), 0);
        r.activity = Activity::Working;
        r.asking = Some(Ask {
            answer: Some("yes".into()),
            kind: AskKind::Confirm,
            ..Ask::note("pick", Clock::at(1_000).wall)
        });
        let id = r.id;
        w.sessions.push(r);
        let mut core = AppCore::new();
        core.dispatch(
            AppAction::StoreLoaded(Ok(Loaded {
                workspaces: vec![w],
                notices: vec![],
                ..Loaded::default()
            })),
            Clock::at(0),
        );
        let e = hook(&mut core, id, stopped(), 2_000);
        assert!(sends(&e).is_empty(), "no pane is known yet");
        assert_eq!(core.session(id).unwrap().activity, Activity::Idle);
        let e = core.dispatch(AppAction::HostListed(vec![running(id)]), Clock::at(3_000));
        assert_eq!(sends(&e), ["Owner answered \"pick\": yes"]);
        assert_eq!(core.session(id).unwrap().asking, None);
        let e = core.dispatch(AppAction::HostListed(vec![running(id)]), Clock::at(4_000));
        assert!(sends(&e).is_empty());
    }

    /// After a failed stop the owner's typed prompt is the reply; the
    /// stored answer is dropped, said so, and never sent after it.
    #[test]
    fn a_prompt_typed_after_a_failed_stop_drops_the_answer() {
        let (mut core, id) = asked("confirm", &[]);
        hook(&mut core, id, EventKind::ToolFinished, 4_000);
        answer(&mut core, id, "yes", 5_000);
        hook(&mut core, id, EventKind::StopFailed { reason: None }, 6_000);
        let e = hook(&mut core, id, EventKind::PromptSubmitted, 7_000);
        assert!(sends(&e).is_empty());
        assert_eq!(core.session(id).unwrap().asking, None);
        let dropped: Vec<_> = core
            .notices()
            .iter()
            .filter(|n| n.text.contains("replaced the answer \"yes\""))
            .collect();
        assert_eq!(dropped.len(), 1);
        let e = hook(&mut core, id, stopped(), 8_000);
        assert!(sends(&e).is_empty());
    }

    /// A fired wakeup or a subagent's hand-back after a failed stop is
    /// not the owner replying: the stored answer waits for the `Stop`.
    #[test]
    fn an_injected_wakeup_keeps_the_answer_for_its_stop() {
        let (mut core, id) = asked("confirm", &[]);
        hook(&mut core, id, EventKind::ToolFinished, 4_000);
        answer(&mut core, id, "yes", 5_000);
        hook(&mut core, id, EventKind::StopFailed { reason: None }, 6_000);
        let e = hook(&mut core, id, EventKind::PromptInjected, 7_000);
        assert!(sends(&e).is_empty());
        let asking = core.session(id).unwrap().asking.as_ref().unwrap();
        assert_eq!(asking.answer.as_deref(), Some("yes"));
        assert!(
            !core
                .notices()
                .iter()
                .any(|n| n.text.contains("replaced the answer"))
        );
        let e = hook(&mut core, id, stopped(), 8_000);
        assert_eq!(sends(&e), ["Owner answered \"pick\": yes"]);
    }

    #[test]
    fn an_answer_that_does_not_fit_the_question_is_refused() {
        let cases: [(Option<&str>, &[&str], &str); 4] = [
            (Some("confirm"), &[], "maybe"),
            (Some("choice"), &["a", "b"], "c"),
            (Some("text"), &[], "  \n"),
            (None, &[], "yes"),
        ];
        for (kind, choices, given) in cases {
            let (mut core, id) = at_prompt(agent());
            assert_eq!(ask(&mut core, ask_op(id, kind, choices), 3_000), None);
            let before = core.session(id).unwrap().clone();
            let e = answer(&mut core, id, given, 4_000);
            assert!(sends(&e).is_empty(), "{kind:?}");
            assert_eq!(saves(&e), 0, "{kind:?}");
            assert_eq!(core.session(id).unwrap(), &before, "{kind:?}");
        }
    }

    #[test]
    fn a_malformed_structured_ask_is_refused() {
        let seven = ["1", "2", "3", "4", "5", "6", "7"];
        let too_many = format!(
            "a choice ask takes at most {} choices",
            crate::core::ASK_CHOICES_MAX
        );
        let cases: [(Option<&str>, &[&str], &str); 6] = [
            (
                Some("choice"),
                &["a"],
                "a choice ask needs at least two choices",
            ),
            (Some("choice"), &seven, &too_many),
            (Some("choice"), &["a", " a "], "each choice must differ"),
            (Some("choice"), &["a", " "], "a choice may not be blank"),
            (
                Some("confirm"),
                &["a", "b"],
                "choices go only with a choice ask",
            ),
            (
                Some("maybe"),
                &[],
                "unknown ask kind; use confirm, choice or text",
            ),
        ];
        for (kind, choices, why) in cases {
            let (mut core, id) = at_prompt(agent());
            assert_eq!(
                ask(&mut core, ask_op(id, kind, choices), 3_000).as_deref(),
                Some(why)
            );
            assert_eq!(core.session(id).unwrap().asking, None, "{why}");
        }
        assert_eq!(seven.len(), crate::core::ASK_CHOICES_MAX + 1);
    }

    /// Only Claude Code's `Stop` says when to send; a Codex pane or a
    /// shell may still ask plainly.
    #[test]
    fn only_claude_code_may_ask_for_an_answer() {
        for kind in [codex(), SessionKind::Shell] {
            let (mut core, id) = at_prompt(kind);
            let why = ask(&mut core, ask_op(id, Some("confirm"), &[]), 3_000);
            assert!(why.unwrap().contains("only a Claude Code session"));
            assert_eq!(core.session(id).unwrap().asking, None);
            assert_eq!(ask(&mut core, ask_op(id, None, &[]), 4_000), None);
            assert!(core.answerable_ask(id).is_none());
        }
    }

    #[test]
    fn a_choice_ask_keeps_its_options_cut_and_in_order() {
        let long = "x".repeat(crate::core::ASK_CHOICE_MAX_CHARS + 5);
        let (mut core, id) = at_prompt(agent());
        assert_eq!(
            ask(
                &mut core,
                ask_op(id, Some("choice"), &[" b ", "a\nmore", &long]),
                3_000
            ),
            None
        );
        let AskKind::Choice(options) = &core.session(id).unwrap().asking.as_ref().unwrap().kind
        else {
            panic!("not a choice");
        };
        assert_eq!(options[..2], ["b".to_owned(), "a".to_owned()]);
        assert_eq!(
            options[2].chars().count(),
            crate::core::ASK_CHOICE_MAX_CHARS + 1
        );
    }

    /// A dismiss, `--clear`, a new spawn and a newer ask each drop a
    /// pending answer with the ask it belonged to.
    #[test]
    fn a_pending_answer_goes_with_its_ask() {
        let held = || {
            let (mut core, id) = asked("confirm", &[]);
            hook(&mut core, id, EventKind::ToolFinished, 4_000);
            answer(&mut core, id, "yes", 5_000);
            assert_eq!(pending(&core, id).as_deref(), Some("yes"));
            (core, id)
        };
        let (mut core, id) = held();
        core.dispatch(AppAction::DismissAsk(id), Clock::at(6_000));
        assert!(sends(&hook(&mut core, id, stopped(), 7_000)).is_empty());

        let (mut core, id) = held();
        let clear = ControlAction::Ask {
            id,
            token: "t".into(),
            message: None,
            kind: None,
            choices: vec![],
        };
        assert_eq!(ask(&mut core, clear, 6_000), None);
        assert!(sends(&hook(&mut core, id, stopped(), 7_000)).is_empty());

        let (mut core, id) = held();
        assert_eq!(ask(&mut core, ask_op(id, Some("text"), &[]), 6_000), None);
        assert_eq!(pending(&core, id), None, "the newest question stands");
        assert!(sends(&hook(&mut core, id, stopped(), 7_000)).is_empty());

        let (mut core, pid, _) = with_records(&[], |_| None);
        let (id, _) = new_session(&mut core, pid, agent(), Launch::Argv(vec![]));
        core.seed_asking(
            id,
            Some(Ask {
                kind: AskKind::Confirm,
                answer: Some("yes".into()),
                ..Ask::note("pick", Clock::at(1).wall)
            }),
        );
        launch_agent(&mut core, id, Some(claude_handle()));
        assert_eq!(core.session(id).unwrap().asking, None);
    }

    #[test]
    fn a_plain_ask_cannot_be_answered_on_a_card() {
        let (mut core, id) = at_prompt(agent());
        assert_eq!(ask(&mut core, ask_op(id, None, &[]), 3_000), None);
        assert!(core.standing_ask_detail(id).is_some());
        assert!(core.answerable_ask(id).is_none());
        core.dispatch(AppAction::HostListed(vec![]), Clock::at(4_000));
        assert_eq!(core.standing_ask_detail(id), None);
    }
}

mod prompting {
    use super::*;
    use crate::core::action::TYPED_HOLD;
    use crate::core::{ControlAction, token_hash};

    fn hook(core: &mut AppCore, id: RecordId, kind: EventKind, at: u64) -> Vec<Effect> {
        core.dispatch(
            AppAction::Events(vec![SessionEvent {
                record_id: Some(id),
                ..event(kind, at)
            }]),
            Clock::at(at + 1),
        )
    }

    fn stopped() -> EventKind {
        EventKind::Stopped {
            last_message: None,
            pending: None,
        }
    }

    /// A running session of `kind` with the token "t", idle after a
    /// `Stop` at 2s.
    fn idle(kind: SessionKind) -> (AppCore, RecordId) {
        let p = project("p");
        let mut w = Workspace::new(p.clone());
        let mut r = record(p.id, kind, 0);
        r.token_hash = Some(token_hash("t"));
        let id = r.id;
        w.sessions.push(r);
        let (mut core, _) = loaded(vec![w], vec![]);
        core.dispatch(AppAction::HostListed(vec![running(id)]), Clock::at(1));
        hook(&mut core, id, stopped(), 2_000);
        (core, id)
    }

    /// Sends a `session.prompt` and returns its refusal and what it
    /// typed. The session's view must agree with the command.
    fn prompt(core: &mut AppCore, id: RecordId, at: u64) -> (Option<String>, Vec<String>) {
        let wall = Clock::at(at).wall;
        let view = core.session_view(id, wall).unwrap().prompt_refusal;
        let op = format!("p{at}");
        let effects = core.dispatch(
            AppAction::Control {
                op: op.clone(),
                action: ControlAction::Prompt {
                    id,
                    text: "Dispatch subscription: events".into(),
                },
            },
            Clock::at(at),
        );
        let error = core.take_control_outcome(&op).unwrap().error;
        assert_eq!(view, error, "the view and the command agree");
        assert!(
            !effects
                .iter()
                .any(|e| matches!(e, Effect::SendMessage { .. })),
            "a delivery settles no box's draft: {effects:?}"
        );
        let typed = effects
            .iter()
            .filter_map(|e| match e {
                Effect::SendInput { text, .. } => Some(text.clone()),
                _ => None,
            })
            .collect();
        (error, typed)
    }

    #[test]
    fn an_idle_claude_session_takes_the_prompt() {
        let (mut core, id) = idle(agent());
        let (error, typed) = prompt(&mut core, id, 3_000);
        assert_eq!(error, None);
        assert_eq!(typed, ["Dispatch subscription: events"]);
    }

    #[test]
    fn each_refusal_names_its_reason() {
        let (mut core, id) = idle(agent());
        core.dispatch(AppAction::HostListed(vec![]), Clock::at(2_500));
        assert_eq!(
            prompt(&mut core, id, 3_000).0.as_deref(),
            Some("not running")
        );

        let (mut core, id) = idle(agent());
        hook(&mut core, id, EventKind::PromptSubmitted, 3_000);
        let (error, typed) = prompt(&mut core, id, 4_000);
        assert_eq!(error.as_deref(), Some("busy"));
        assert!(typed.is_empty());

        let (mut core, id) = idle(agent());
        hook(
            &mut core,
            id,
            EventKind::PermissionRequested {
                tool: Some("Bash".into()),
            },
            3_000,
        );
        assert_eq!(
            prompt(&mut core, id, 4_000).0.as_deref(),
            Some("at a prompt (permission for Bash)")
        );

        let (mut core, id) = idle(agent());
        core.prompted.push(id);
        assert_eq!(
            prompt(&mut core, id, 3_000).0.as_deref(),
            Some("at a prompt (trust)")
        );

        let (mut core, id) = idle(agent());
        hook(
            &mut core,
            id,
            EventKind::StopFailed {
                reason: Some("rate_limit".into()),
            },
            3_000,
        );
        assert_eq!(
            prompt(&mut core, id, 4_000).0.as_deref(),
            Some("at a prompt (rate limit)")
        );

        let (mut core, id) = idle(codex());
        assert_eq!(
            prompt(&mut core, id, 3_000).0.as_deref(),
            Some("not a Claude Code session")
        );
    }

    /// The owner's keys in the embedded terminal hold deliveries off
    /// until a prompt is submitted or `TYPED_HOLD` passes.
    #[test]
    fn typing_holds_the_prompt_off() {
        let hold = u64::try_from(TYPED_HOLD.as_millis()).unwrap();
        let (mut core, id) = idle(agent());
        let effects = core.dispatch(AppAction::InputTyped { id }, Clock::at(3_000));
        assert_eq!(saves(&effects), 0, "the mark is transient");
        assert_eq!(
            prompt(&mut core, id, 4_000).0.as_deref(),
            Some("the owner is typing")
        );
        let (error, typed) = prompt(&mut core, id, 3_000 + hold);
        assert_eq!(error, None, "the mark expires");
        assert_eq!(typed.len(), 1);

        let (mut core, id) = idle(agent());
        core.dispatch(AppAction::InputTyped { id }, Clock::at(3_000));
        hook(&mut core, id, EventKind::PromptSubmitted, 4_000);
        hook(&mut core, id, stopped(), 5_000);
        assert_eq!(prompt(&mut core, id, 6_000).0, None, "a prompt clears it");
    }

    /// The pane reads as between turns until Claude Code reports the
    /// typed prompt, so a second one in that window is refused.
    #[test]
    fn a_second_prompt_waits_for_the_first_to_land() {
        let (mut core, id) = idle(agent());
        assert_eq!(prompt(&mut core, id, 3_000).0, None);
        assert_eq!(
            prompt(&mut core, id, 3_500).0.as_deref(),
            Some("a prompt is being submitted"),
            "not blamed on the owner"
        );
        hook(&mut core, id, EventKind::PromptSubmitted, 4_000);
        assert_eq!(prompt(&mut core, id, 4_500).0.as_deref(), Some("busy"));
        hook(&mut core, id, stopped(), 5_000);
        assert_eq!(prompt(&mut core, id, 6_000).0, None);
    }

    /// An answer of the owner's goes first; an idle session's own ask
    /// with no answer does not block, and the delivery does not clear it.
    #[test]
    fn the_owners_answer_goes_first_and_an_open_ask_stays() {
        let (mut core, id) = idle(agent());
        let ask = ControlAction::Ask {
            id,
            token: "t".into(),
            message: Some("pick".into()),
            kind: Some("text".into()),
            choices: vec![],
        };
        core.dispatch(
            AppAction::Control {
                op: "a".into(),
                action: ask,
            },
            Clock::at(3_000),
        );
        assert_eq!(prompt(&mut core, id, 4_000).0, None);
        hook(&mut core, id, EventKind::PromptSubmitted, 5_000);
        assert!(core.session(id).unwrap().asking.is_some());

        // An answer given mid-turn waits on the record for the `Stop`.
        let at = core.session(id).unwrap().asking.as_ref().unwrap().at;
        core.dispatch(
            AppAction::AnswerAsk {
                id,
                at,
                answer: "main".into(),
            },
            Clock::at(6_000),
        );
        assert_eq!(
            prompt(&mut core, id, 6_500).0.as_deref(),
            Some("an answer waits")
        );
        hook(&mut core, id, stopped(), 7_000);
        assert_eq!(
            core.session(id).unwrap().asking,
            None,
            "the answer went out"
        );
    }

    /// `ready_for_prompt` is `Ok` exactly when `deliver_answer` would
    /// send, for every activity, with nothing else in the way.
    #[test]
    fn readiness_agrees_with_the_answer_rule() {
        let (mut core, id) = idle(agent());
        let wall = Clock::at(3_000).wall;
        let activities = [
            Activity::Unknown,
            Activity::Working,
            Activity::WaitingOnYou,
            Activity::Idle,
            Activity::Ended,
        ];
        for started in [false, true] {
            for activity in activities {
                core.started.retain(|r| *r != id);
                if started {
                    core.started.push(id);
                }
                core.workspaces[0].sessions[0].activity = activity;
                assert_eq!(
                    core.ready_for_prompt(id, wall).is_ok(),
                    core.between_turns(id),
                    "{activity:?}, started {started}"
                );
            }
        }
    }
}

#[test]
fn evidence_opens_documents_and_images_and_refuses_what_would_run() {
    use crate::core::dispatch::{evidence_inline, evidence_opens};
    use std::path::Path;
    assert!(evidence_opens(Path::new("/e/shot.PNG")));
    assert!(evidence_opens(Path::new("/e/r.pdf")));
    for refused in [
        "x.command",
        "a.app",
        "page.html",
        "t.terminal",
        "s.scpt",
        "p.pkg",
        "noext",
    ] {
        assert!(!evidence_opens(Path::new(refused)), "{refused}");
    }
    assert!(evidence_inline(Path::new("steps.MD")));
    assert!(!evidence_inline(Path::new("shot.png")));
}

mod remote {
    //! The remote port's state: identity, devices, the pairing window.
    use super::*;
    use crate::core::{PAIRING_ATTEMPTS, PAIRING_WINDOW, PairingWindow};
    use crate::ports::remote::{Identity, Listen, PairedDevice, Scope};
    use crate::ports::store::Loaded;

    fn identity() -> Identity {
        Identity {
            schema_version: 1,
            server_id: uuid::Uuid::new_v4(),
            server_name: "Studio".into(),
            certificate: "MIIB".into(),
            spki_sha256: "ab".repeat(32),
            created: Clock::at(0).wall,
            listen: Listen::default(),
        }
    }

    fn device(name: &str, hash: &str) -> PairedDevice {
        PairedDevice {
            id: uuid::Uuid::new_v4(),
            name: name.into(),
            scope: Scope::Read,
            token_sha256: hash.into(),
            created: Clock::at(0).wall,
            last_seen: None,
        }
    }

    #[test]
    fn the_invite_is_a_url_whose_fragment_carries_the_code() {
        let identity = identity();
        let window = PairingWindow {
            until: Clock::at(0).mono,
            code: "K7M2QX".into(),
            scope: Scope::Read,
            failures: 0,
        };
        let url =
            crate::core::invite_url(&identity, &window, Some("192.168.1.20".parse().unwrap()), 7077);
        assert_eq!(
            url,
            format!(
                "https://192.168.1.20:7077/#code=K7M2QX&key={}&id={}",
                identity.spki_sha256, identity.server_id
            )
        );
        assert!(!url.contains('?'), "nothing the server would receive");
        let loopback = crate::core::invite_url(&identity, &window, "127.0.0.1".parse().unwrap(), 9);
        assert!(loopback.starts_with("https://127.0.0.1:9/#code="));
        let v6 = crate::core::invite_url(&identity, &window, "fe80::1".parse().unwrap(), 9);
        assert!(v6.starts_with("https://[fe80::1]:9/#"));
    }

    #[test]
    fn a_cookie_is_found_by_its_exact_name() {
        let header = "a=1; __Host-sb-x=tok; __Host-sb=old; b=2";
        assert_eq!(
            crate::core::cookie_value(header, "__Host-sb-x"),
            Some("tok")
        );
        assert_eq!(crate::core::cookie_value(header, "__Host-sb"), Some("old"));
        assert_eq!(crate::core::cookie_value(header, "__Host-sb-y"), None);
        assert_eq!(
            crate::core::cookie_value("__Host-sb-x=", "__Host-sb-x"),
            None
        );
    }

    fn loaded_core() -> AppCore {
        let mut core = AppCore::new();
        core.dispatch(AppAction::StoreLoaded(Ok(Loaded::default())), Clock::at(0));
        core.dispatch(
            AppAction::IdentityLoaded {
                identity: identity(),
                devices: vec![device("Vision Pro", "h1")],
                rotated: false,
            },
            Clock::at(0),
        );
        core
    }

    #[test]
    fn the_identity_loads_and_a_rename_or_an_address_change_saves_it() {
        let mut core = loaded_core();
        assert_eq!(core.identity().unwrap().server_name, "Studio");
        assert_eq!(core.devices().len(), 1);
        assert!(!core.identity_rotated());
        let e = core.dispatch(AppAction::SetServerName("  Desk  ".into()), Clock::at(1));
        assert_eq!(core.identity().unwrap().server_name, "Desk");
        assert!(
            matches!(e.as_slice(), [Effect::SaveIdentity(i)] if i.server_name == "Desk"),
            "{e:?}"
        );
        let e = core.dispatch(AppAction::SetServerName("   ".into()), Clock::at(2));
        assert_eq!(
            core.identity().unwrap().server_name,
            "Desk",
            "a blank name is ignored"
        );
        assert!(e.is_empty(), "{e:?}");
        let e = core.dispatch(AppAction::SetServerName("Desk".into()), Clock::at(3));
        assert!(e.is_empty(), "an unchanged name saves nothing: {e:?}");
        let e = core.dispatch(
            AppAction::SetRemoteListen {
                lan: true,
                port: 5000,
            },
            Clock::at(4),
        );
        let listen = &core.identity().unwrap().listen;
        assert!(listen.lan);
        assert_eq!(listen.port, 5000);
        assert!(matches!(e.as_slice(), [Effect::SaveIdentity(_)]), "{e:?}");
        let e = core.dispatch(
            AppAction::SetRemoteListen { lan: true, port: 0 },
            Clock::at(5),
        );
        assert_eq!(
            core.identity().unwrap().listen.port,
            5000,
            "port 0 is refused"
        );
        assert!(e.is_empty(), "{e:?}");
    }

    #[test]
    fn a_rotated_identity_says_so_and_a_read_only_core_saves_nothing() {
        let mut core = AppCore::new();
        core.dispatch(
            AppAction::StoreLoaded(Err(crate::ports::store::StoreError::Locked)),
            Clock::at(0),
        );
        core.dispatch(
            AppAction::IdentityLoaded {
                identity: identity(),
                devices: Vec::new(),
                rotated: true,
            },
            Clock::at(0),
        );
        assert!(core.identity_rotated());
        let e = core.dispatch(AppAction::SetServerName("Desk".into()), Clock::at(1));
        assert_eq!(core.identity().unwrap().server_name, "Desk");
        assert!(e.is_empty(), "read-only: {e:?}");
        let e = core.dispatch(AppAction::Paired(device("Pad", "h2")), Clock::at(2));
        assert_eq!(core.devices().len(), 1);
        assert!(e.is_empty(), "read-only: {e:?}");
    }

    #[test]
    fn the_pairing_window_opens_with_its_code_closes_on_time_and_after_three_failures() {
        let mut core = loaded_core();
        assert!(core.pairing().is_none());
        let e = core.dispatch(
            AppAction::OpenPairing {
                code: "ABCD2345".into(),
                scope: Scope::Control,
            },
            Clock::at(1_000),
        );
        assert!(e.is_empty(), "the window is never saved: {e:?}");
        let window = core.pairing_at(Clock::at(1_000)).unwrap();
        assert_eq!(window.code, "ABCD2345");
        assert_eq!(window.scope, Scope::Control);
        assert_eq!(window.failures, 0);
        let end = 1_000 + u64::try_from(PAIRING_WINDOW.as_millis()).unwrap();
        assert!(core.pairing_at(Clock::at(end - 1)).is_some());
        assert!(
            core.pairing_at(Clock::at(end)).is_none(),
            "passed between ticks"
        );
        core.dispatch(AppAction::Tick, Clock::at(end));
        assert!(core.pairing().is_none(), "the tick clears it");

        core.dispatch(
            AppAction::OpenPairing {
                code: "ABCD2345".into(),
                scope: Scope::Read,
            },
            Clock::at(2_000),
        );
        for n in 1..PAIRING_ATTEMPTS {
            core.dispatch(AppAction::PairingFailed, Clock::at(2_000 + u64::from(n)));
            assert_eq!(core.pairing().unwrap().failures, n);
        }
        core.dispatch(AppAction::PairingFailed, Clock::at(2_100));
        assert!(core.pairing().is_none(), "the third failure closes it");
        assert!(
            core.notice()
                .is_some_and(|n| n.text.contains("Pairing closed"))
        );
        core.dispatch(AppAction::PairingFailed, Clock::at(2_200));
        assert!(
            core.pairing().is_none(),
            "a failure with no window is nothing"
        );

        core.dispatch(
            AppAction::OpenPairing {
                code: "ZZZZ2345".into(),
                scope: Scope::Read,
            },
            Clock::at(3_000),
        );
        core.dispatch(AppAction::ClosePairing, Clock::at(3_001));
        assert!(core.pairing().is_none());
    }

    #[test]
    fn a_pairing_spends_the_code_keeps_the_device_and_saves_the_file() {
        let mut core = loaded_core();
        core.dispatch(
            AppAction::OpenPairing {
                code: "ABCD2345".into(),
                scope: Scope::Control,
            },
            Clock::at(1_000),
        );
        let made = core.new_device("  iPad  ", "h2".into(), Clock::at(1_001).wall);
        assert_eq!(made.name, "iPad");
        assert_eq!(made.scope, Scope::Control, "the window's scope");
        assert_eq!(made.token_sha256, "h2");
        let e = core.dispatch(AppAction::Paired(made.clone()), Clock::at(1_001));
        assert!(core.pairing().is_none(), "single use");
        assert_eq!(core.devices().len(), 2);
        assert_eq!(core.device_by_token("h2"), Some(&made));
        assert!(
            matches!(e.as_slice(), [Effect::SaveDevices(d)] if d.len() == 2),
            "{e:?}"
        );
        assert_eq!(
            core.new_device("x", "h3".into(), Clock::at(0).wall).scope,
            Scope::Read
        );
    }

    #[test]
    fn revoke_removes_a_scope_change_saves_and_a_seen_device_saves_rarely() {
        let mut core = loaded_core();
        let id = core.devices()[0].id;
        let e = core.dispatch(
            AppAction::SetDeviceScope {
                device: id,
                scope: Scope::Control,
            },
            Clock::at(1),
        );
        assert_eq!(core.devices()[0].scope, Scope::Control);
        assert!(matches!(e.as_slice(), [Effect::SaveDevices(_)]), "{e:?}");
        let e = core.dispatch(
            AppAction::SetDeviceScope {
                device: id,
                scope: Scope::Control,
            },
            Clock::at(2),
        );
        assert!(e.is_empty(), "unchanged: {e:?}");

        let e = core.dispatch(AppAction::DeviceSeen(id), Clock::at(10_000));
        assert_eq!(core.devices()[0].last_seen, Some(Clock::at(10_000).wall));
        assert!(
            matches!(e.as_slice(), [Effect::SaveDevices(_)]),
            "first sight: {e:?}"
        );
        let e = core.dispatch(AppAction::DeviceSeen(id), Clock::at(20_000));
        assert_eq!(core.devices()[0].last_seen, Some(Clock::at(20_000).wall));
        assert!(e.is_empty(), "ten seconds later: {e:?}");
        let e = core.dispatch(AppAction::DeviceSeen(id), Clock::at(400_000));
        assert!(
            matches!(e.as_slice(), [Effect::SaveDevices(_)]),
            "minutes later: {e:?}"
        );
        let e = core.dispatch(
            AppAction::DeviceSeen(uuid::Uuid::new_v4()),
            Clock::at(400_001),
        );
        assert!(e.is_empty(), "unknown: {e:?}");

        let e = core.dispatch(AppAction::RevokeDevice(id), Clock::at(3));
        assert!(core.devices().is_empty());
        assert!(
            matches!(e.as_slice(), [Effect::SaveDevices(d)] if d.is_empty()),
            "{e:?}"
        );
        let e = core.dispatch(AppAction::RevokeDevice(id), Clock::at(4));
        assert!(e.is_empty(), "already gone: {e:?}");
    }
}

mod revision {
    //! The read-model fingerprints behind the remote port's revision.

    use super::*;
    use crate::core::revision::{Fingerprints, ResourceKind};

    fn changed(fp: &Fingerprints, next: &Fingerprints) -> Vec<(ResourceKind, String, bool)> {
        fp.changes(next)
            .into_iter()
            .map(|c| (c.resource.kind, c.resource.id, c.removed))
            .collect()
    }

    #[test]
    fn age_alone_changes_nothing_but_the_quiet_transition_does() {
        let p = project("p");
        let mut w = Workspace::new(p.clone());
        let r = record(p.id, codex(), 0);
        let id = r.id;
        w.sessions.push(r);
        let (mut core, _) = loaded(vec![w], vec![]);
        let now = Clock::at(60_000);
        let mut status = running(id);
        status.last_activity = Some(now.wall - Duration::from_secs(5));
        core.dispatch(AppAction::HostListed(vec![status.clone()]), now);
        let first = Fingerprints::of(&core, now.wall);
        assert!(
            first.len() > 4,
            "projects, spaces, the session, its collections"
        );
        // Ten seconds later with nothing listed again: `quiet_secs`
        // moved on every session view and nothing else did.
        let later = Fingerprints::of(&core, now.wall + Duration::from_secs(10));
        assert_eq!(changed(&first, &later), vec![]);
        // The pane passes the quiet interval: the card's word moves.
        status.last_activity = Some(now.wall - Duration::from_secs(30));
        core.dispatch(AppAction::HostListed(vec![status]), now);
        let quiet = Fingerprints::of(&core, now.wall);
        assert_eq!(
            changed(&later, &quiet),
            vec![(ResourceKind::Session, id.0.to_string(), false)]
        );
    }

    #[test]
    fn the_tickets_move_as_one_collection_when_a_status_changes_them() {
        use crate::ports::dispatch::{DecisionView, Status, TicketView};
        let (mut core, _) = loaded(vec![], vec![]);
        let quiet = Fingerprints::of(&core, Clock::at(1).wall);
        let mut status = Status {
            tickets: vec![TicketView {
                id: "t1".into(),
                project: "Orchard".into(),
                state: "active".into(),
                decisions: vec![DecisionView {
                    id: "d1".into(),
                    ticket: "t1".into(),
                    state: "pending".into(),
                    ..DecisionView::default()
                }],
                ..TicketView::default()
            }],
            ..Status::default()
        };
        core.dispatch(
            AppAction::DispatchStatus(Some(status.clone())),
            Clock::at(2),
        );
        let listed = Fingerprints::of(&core, Clock::at(2).wall);
        assert_eq!(
            changed(&quiet, &listed),
            vec![(ResourceKind::Tickets, String::new(), false)]
        );
        // The same status again, the runner's order aside, is no change.
        core.dispatch(
            AppAction::DispatchStatus(Some(status.clone())),
            Clock::at(3),
        );
        let same = Fingerprints::of(&core, Clock::at(3).wall);
        assert_eq!(changed(&listed, &same), vec![]);
        // A decision answered moves the ticket's standing.
        status.tickets[0].decisions[0].state = "answered".into();
        core.dispatch(AppAction::DispatchStatus(Some(status)), Clock::at(4));
        let answered = Fingerprints::of(&core, Clock::at(4).wall);
        assert_eq!(
            changed(&same, &answered),
            vec![(ResourceKind::Tickets, String::new(), false)]
        );
        assert_eq!(core.ticket_listing().tickets[0].standing, "queued");
        // The runner gone: the listing says so, the tickets stay.
        core.dispatch(AppAction::DispatchStatus(None), Clock::at(5));
        let gone = Fingerprints::of(&core, Clock::at(5).wall);
        assert_eq!(
            changed(&answered, &gone),
            vec![(ResourceKind::Tickets, String::new(), false)]
        );
        assert!(!core.ticket_listing().connected);
        assert_eq!(core.ticket_listing().tickets.len(), 1);
    }

    #[test]
    fn a_removed_session_is_removed_and_its_collection_changed() {
        let (mut core, pid, ids) =
            with_records(&[SessionKind::Shell, SessionKind::Shell], |_| None);
        let before = Fingerprints::of(&core, Clock::at(1).wall);
        core.dispatch(AppAction::RemoveSession(ids[0]), Clock::at(2));
        let after = Fingerprints::of(&core, Clock::at(2).wall);
        let mut moved = changed(&before, &after);
        moved.sort();
        assert_eq!(
            moved,
            vec![
                (ResourceKind::Session, ids[0].0.to_string(), true),
                (ResourceKind::Sessions, pid.0.to_string(), false),
            ]
        );
        assert_eq!(
            changed(&after, &after),
            vec![],
            "a pass with nothing moving"
        );
    }

    #[test]
    fn a_set_rename_and_a_trust_question_move_only_their_resource() {
        let (mut core, _pid, ids) =
            with_records(&[SessionKind::Agent(AgentKind::ClaudeCode)], |s| {
                Some(running(s.id))
            });
        core.dispatch(
            AppAction::NewWorkingSet {
                name: Some("Desk".into()),
                clone_of: None,
                with: None,
                columns: 4,
            },
            Clock::at(1),
        );
        let set = core
            .set_views(SpaceId::GLOBAL)
            .into_iter()
            .chain(
                core.space_views()
                    .iter()
                    .filter_map(|s| Uuid::parse_str(&s.id).ok())
                    .flat_map(|s| core.set_views(SpaceId(s))),
            )
            .find(|s| s.name == "Desk")
            .expect("the set");
        let before = Fingerprints::of(&core, Clock::at(2).wall);
        core.dispatch(
            AppAction::RenameWorkingSet {
                set: SetId(Uuid::parse_str(&set.id).unwrap()),
                name: "Bench".into(),
            },
            Clock::at(3),
        );
        let renamed = Fingerprints::of(&core, Clock::at(3).wall);
        assert_eq!(
            changed(&before, &renamed),
            vec![(ResourceKind::Set, set.id.clone(), false)]
        );
        core.dispatch(
            AppAction::PromptSeen {
                id: ids[0],
                seen: true,
            },
            Clock::at(4),
        );
        let asked = Fingerprints::of(&core, Clock::at(4).wall);
        let moved = changed(&renamed, &asked);
        assert!(
            moved.contains(&(ResourceKind::Session, ids[0].0.to_string(), false)),
            "{moved:?}"
        );
        assert!(
            moved.contains(&(ResourceKind::Waiting, String::new(), false)),
            "the trust question waits on the owner: {moved:?}"
        );
    }
}

mod updates {
    use super::*;
    use crate::core::updates::{UPDATE_CHECK_INTERVAL, UPDATE_FIRST_CHECK, UpdateState, is_newer};
    use crate::ports::updates::Release;

    fn release(version: &str) -> Release {
        Release {
            version: version.into(),
            notes: "notes".into(),
            asset_url: "https://x/Switchboard.zip".into(),
            asset_name: "Switchboard.zip".into(),
            digest_url: Some("https://x/Switchboard.zip.sha256".into()),
        }
    }

    fn core() -> AppCore {
        let mut core = AppCore::new();
        core.set_version("0.2.0");
        core
    }

    fn ms(d: Duration) -> u64 {
        u64::try_from(d.as_millis()).unwrap()
    }

    #[test]
    fn only_a_parsed_higher_version_without_a_prerelease_is_newer() {
        assert!(is_newer("0.2.1", "0.2.0"));
        assert!(is_newer("v1.0.0", "0.9.9"));
        assert!(!is_newer("0.2.0", "0.2.0"));
        assert!(!is_newer("0.1.9", "0.2.0"));
        assert!(
            !is_newer("0.3.0-rc1", "0.2.0"),
            "a pre-release is never offered"
        );
        assert!(!is_newer("0.1.0-20261014-1d8f4e8", "0.1.0"));
        assert!(
            !is_newer("latest", "0.2.0"),
            "a malformed tag pulls nothing"
        );
        assert!(!is_newer("0.3.0", "junk"));
    }

    #[test]
    fn the_tick_checks_once_the_app_has_settled_and_then_hourly() {
        let mut core = core();
        let first = ms(UPDATE_FIRST_CHECK);
        let e = core.dispatch(AppAction::Tick, Clock::at(first - 1));
        assert!(!e.contains(&Effect::CheckForUpdate));
        assert_eq!(*core.update(), UpdateState::Idle);
        let e = core.dispatch(AppAction::Tick, Clock::at(first));
        assert!(e.contains(&Effect::CheckForUpdate));
        assert_eq!(*core.update(), UpdateState::Checking);
        let e = core.dispatch(AppAction::Tick, Clock::at(first + 1));
        assert!(!e.contains(&Effect::CheckForUpdate), "one check at a time");

        core.dispatch(AppAction::UpdateChecked(Ok(None)), Clock::at(first + 2));
        assert_eq!(*core.update(), UpdateState::UpToDate);
        let again = first + ms(UPDATE_CHECK_INTERVAL);
        let e = core.dispatch(AppAction::Tick, Clock::at(again - 1));
        assert!(!e.contains(&Effect::CheckForUpdate));
        let e = core.dispatch(AppAction::Tick, Clock::at(again));
        assert!(e.contains(&Effect::CheckForUpdate));
    }

    #[test]
    fn a_newer_release_is_offered_once_and_the_rest_leave_the_app_up_to_date() {
        let mut core = core();
        core.dispatch(AppAction::CheckForUpdate, Clock::at(1));
        core.dispatch(
            AppAction::UpdateChecked(Ok(Some(release("0.2.0")))),
            Clock::at(2),
        );
        assert_eq!(*core.update(), UpdateState::UpToDate);
        core.dispatch(AppAction::CheckForUpdate, Clock::at(3));
        core.dispatch(
            AppAction::UpdateChecked(Err("offline".into())),
            Clock::at(4),
        );
        assert_eq!(
            *core.update(),
            UpdateState::Failed {
                reason: "offline".into(),
                release: None
            }
        );
        assert!(core.notices().is_empty(), "a failed check is quiet");

        core.dispatch(AppAction::CheckForUpdate, Clock::at(5));
        core.dispatch(
            AppAction::UpdateChecked(Ok(Some(release("0.3.0")))),
            Clock::at(6),
        );
        assert_eq!(*core.update(), UpdateState::Available(release("0.3.0")));
        assert_eq!(core.notices().len(), 1);
        assert!(core.notices()[0].text.contains("0.3.0"));
        assert!(!core.notices()[0].is_error);

        // The hourly check finds the same release: nothing new to say.
        core.dispatch(AppAction::CheckForUpdate, Clock::at(7));
        core.dispatch(
            AppAction::UpdateChecked(Ok(Some(release("0.3.0")))),
            Clock::at(8),
        );
        assert_eq!(*core.update(), UpdateState::Available(release("0.3.0")));
        assert_eq!(core.notices().len(), 1);
    }

    #[test]
    fn the_download_and_the_install_are_two_clicks_and_a_failure_keeps_the_release() {
        let mut core = core();
        core.dispatch(AppAction::CheckForUpdate, Clock::at(1));
        core.dispatch(
            AppAction::UpdateChecked(Ok(Some(release("0.3.0")))),
            Clock::at(2),
        );
        let e = core.dispatch(AppAction::DownloadUpdate, Clock::at(3));
        assert!(e.contains(&Effect::DownloadUpdate(release("0.3.0"))));
        assert_eq!(*core.update(), UpdateState::Downloading(release("0.3.0")));
        let e = core.dispatch(AppAction::Tick, Clock::at(3 + ms(UPDATE_CHECK_INTERVAL)));
        assert!(
            !e.contains(&Effect::CheckForUpdate),
            "no check under a download"
        );

        core.dispatch(
            AppAction::UpdateDownloaded(Err("checksum".into())),
            Clock::at(4),
        );
        assert_eq!(
            *core.update(),
            UpdateState::Failed {
                reason: "checksum".into(),
                release: Some(release("0.3.0"))
            }
        );
        assert!(core.notices().last().unwrap().is_error);
        let e = core.dispatch(AppAction::DownloadUpdate, Clock::at(5));
        assert!(
            e.contains(&Effect::DownloadUpdate(release("0.3.0"))),
            "tried again"
        );

        let staged = PathBuf::from("/tmp/staged/Switchboard.app");
        core.dispatch(
            AppAction::UpdateDownloaded(Ok(staged.clone())),
            Clock::at(6),
        );
        assert_eq!(
            *core.update(),
            UpdateState::Ready {
                release: release("0.3.0"),
                staged: staged.clone()
            }
        );
        assert!(
            !core
                .dispatch(AppAction::Tick, Clock::at(6 + ms(UPDATE_CHECK_INTERVAL)))
                .contains(&Effect::CheckForUpdate),
            "a ready update is not checked over"
        );
        let e = core.dispatch(AppAction::InstallUpdate, Clock::at(7));
        assert!(e.contains(&Effect::InstallUpdate(staged)));
        core.dispatch(
            AppAction::UpdateInstallFailed("read-only".into()),
            Clock::at(8),
        );
        assert!(matches!(
            core.update(),
            UpdateState::Failed { release: Some(r), .. } if r.version == "0.3.0"
        ));
        assert!(core.notices().last().unwrap().text.contains("read-only"));
    }
}

mod tickets {
    //! The port's view of a ticket's files and events.

    use super::*;
    use crate::core::tickets::file_key;
    use crate::ports::dispatch::{AttemptView, ChecksView, EvidenceView, Status, TicketView};

    fn status() -> Status {
        Status {
            tickets: vec![TicketView {
                id: "t1".into(),
                project: "Orchard".into(),
                state: "active".into(),
                attempts: vec![AttemptView {
                    stage: "try".into(),
                    n: 2,
                    artifacts: vec![
                        ("notes".into(), "/d/t1/try/2/joined/notes.md".into()),
                        ("token".into(), "/d/t1/try/2/joined/token".into()),
                    ],
                    secret: vec!["token".into()],
                    checks: Some(ChecksView {
                        head: "abc".into(),
                        exit: Some(1),
                        log: "/d/t1/try/2/joined/checks.log".into(),
                    }),
                    evidence: vec![
                        EvidenceView {
                            path: "/d/t1/try/2/joined/evidence/Shot.PNG".into(),
                            rel: "Shot.PNG".into(),
                            bytes: 9,
                            modified_ms: 5,
                        },
                        EvidenceView {
                            path: "/d/t1/try/2/joined/evidence/run.command".into(),
                            rel: "run.command".into(),
                            bytes: 9,
                            modified_ms: 5,
                        },
                    ],
                    ..AttemptView::default()
                }],
                ..TicketView::default()
            }],
            ..Status::default()
        }
    }

    #[test]
    fn a_file_is_found_by_the_key_that_stands_for_its_path() {
        let (mut core, _) = loaded(vec![], vec![]);
        core.dispatch(AppAction::DispatchStatus(Some(status())), Clock::at(2));
        let detail = core.ticket_detail("t1").unwrap();
        let files = &detail.attempts[0].files;
        let names: Vec<&str> = files.iter().map(|f| f.name.as_str()).collect();
        assert_eq!(
            names,
            ["notes", "token", "checks", "Shot.PNG", "run.command"]
        );
        let kinds: Vec<&str> = files.iter().map(|f| f.kind.as_str()).collect();
        assert_eq!(
            kinds,
            ["artifact", "secret", "checks", "evidence", "evidence"]
        );
        // Text artifacts and the log read inline; a secret never; the
        // picture is an image whatever its case; a script is neither.
        let inline: Vec<bool> = files.iter().map(|f| f.inline).collect();
        assert_eq!(inline, [true, false, true, false, false]);
        let image: Vec<bool> = files.iter().map(|f| f.image).collect();
        assert_eq!(image, [false, false, false, true, false]);
        assert_eq!(files[3].bytes, Some(9));
        assert_eq!(detail.attempts[0].checks.as_ref().unwrap().exit, Some(1));

        let key = file_key(std::path::Path::new("/d/t1/try/2/joined/notes.md"));
        assert_eq!(
            files[0].key, key,
            "the key is the path's, so a device may hold it"
        );
        let (found, path) = core.ticket_file("t1", &key).unwrap();
        assert_eq!(found.name, "notes");
        assert_eq!(
            path,
            std::path::PathBuf::from("/d/t1/try/2/joined/notes.md")
        );
        assert!(core.ticket_file("t1", "nope").is_none());
        assert!(core.ticket_file("t2", &key).is_none());
    }

    #[test]
    fn events_read_as_the_cache_holds_them() {
        use crate::ports::dispatch::{Body, EventView, EventsView, Reply};
        let (mut core, _) = loaded(vec![], vec![]);
        core.dispatch(AppAction::DispatchStatus(Some(status())), Clock::at(2));
        let none = core.ticket_events("t1");
        assert!(none.events.is_empty() && none.last == 0 && !none.unavailable);
        core.dispatch(
            AppAction::DispatchReplied {
                body: Body::Events {
                    ticket: "t1".into(),
                    since: 0,
                },
                result: Ok(Reply::Events(EventsView {
                    events: vec![EventView {
                        seq: 7,
                        at_ms: 3,
                        stage: "try".into(),
                        kind: "attempt-started".into(),
                        text: "joined #2 agent".into(),
                        attempt: Some(("try".into(), 2)),
                        ..EventView::default()
                    }],
                    last: 7,
                    withdrawn: vec![],
                })),
            },
            Clock::at(3),
        );
        let read = core.ticket_events("t1");
        assert_eq!(read.last, 7);
        assert_eq!(read.events[0].attempt.as_deref(), Some("try/2"));
        assert_eq!(read.events[0].text, "joined #2 agent");
    }
}

