  if (info.spki_sha256 !== invite.key || info.server_id !== invite.id) {
    message(
      'Different Switchboard',
      'This address is a different Switchboard than the code was for. Nothing was sent.',
    );
    return;
  }
  const r = await call(API.pair, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      code: invite.code,
      spki_sha256: invite.key,
      device_name: deviceName(navigator.userAgent, navigator.maxTouchPoints),
      transport: 'cookie',
    }),
  });
  if (r.status !== 200) {
    const code = r.body && r.body.error && r.body.error.code;
    message('Not paired', PAIR_ERRORS[code] || 'Pairing failed.');
    return;
  }
  page.stored = {
    server_id: info.server_id,
    spki_sha256: info.spki_sha256,
    server_name: info.server_name,
  };
  saveStored(page.stored);
  await start(true);
}

async function boot() {
  page.stored = loadStored();
  const invite = parseFragment(location.hash);
  if (invite) {
    // Before anything else: the code is single use, but it should not
    // stay in the address bar.
    history.replaceState(null, '', location.pathname);
    await pairFrom(invite);
    return;
  }
  await start();
}

async function start() {
  let r;
  try {
    r = await call(API.me);
  } catch {
    message('Cannot reach the host', 'Check that the Mac is awake and on the same network.');
    return;
  }
  if (r.status === 401) {
    await unauthorized();
    return;
  }
  if (r.status !== 200) {
    message('Error', 'The host did not answer as expected.');
    return;
  }
  page.me = r.body.body;
  document.getElementById('host-name').textContent = page.me.server_name;
  document.getElementById('scope').textContent = `${page.me.scope} access`;
  document.getElementById('bar').hidden = false;
  await refresh();
  startPolling(POLL_FAST);
  connectSocket();
}

// --- reading

async function refresh() {
  if (page.refreshing) return;
  page.refreshing = true;
  try {
    const waiting = await call(API.waiting);
    if (waiting.status === 401) return await unauthorized();
    if (waiting.status !== 200) return;
    if (!isCurrent(page.applied, waiting.body)) return;
    const projects = await call(API.projects);
    if (projects.status === 401) return await unauthorized();
    if (projects.status !== 200) return;
    const groups = [];
    for (const project of projects.body.body.projects) {
      const r = await call(route(API.sessions, project.id));
      if (r.status === 200) groups.push({ project, sessions: r.body.body.sessions });
    }
    page.groups = arrange(groups);
    page.applied = { epoch: waiting.body.epoch, revision: waiting.body.revision };
    if (page.open) await readSession(true);
    else drawList();
  } catch {
    // A dropped network: the next poll tries again.
  } finally {
    page.refreshing = false;
  }
}

function drawList() {
  const nodes = [];
  const now = Date.now();
  for (const group of page.groups) {
    if (group.sessions.length === 0) continue;
    nodes.push(el('h2', group.project.name));
    for (const s of group.sessions) {
      const row = el('button', null, s.waiting ? 'row waiting' : 'row');
      if (s.waiting) {
        const reason = s.waiting_reason ? `: ${s.waiting_reason}` : '';
        row.append(el('span', `Waiting on you${reason}`, 'flag'));
      }
      row.append(el('strong', s.name));
      row.append(el('span', `${s.kind} · ${s.card} · ${ago(s.last_activity_ms, now)}`, 'meta'));
      row.addEventListener('click', () => openSession(s));
      nodes.push(row);
    }
  }
  if (nodes.length === 0) nodes.push(el('p', 'No sessions.', 'note'));
  show(...nodes);
}

function findSession(id) {
  for (const group of page.groups) {
    const s = group.sessions.find((x) => x.id === id);
    if (s) return s;
  }
  return null;
}

async function openSession(s) {
  page.open = s.id;
  await readSession(true);
}

// Read the open session's content. Every read renews the host's watch
// on its key. `redraw` forces a draw when the content is unchanged, for
// a list change such as the waiting flag.
async function readSession(redraw) {
  const s = findSession(page.open);
  if (!s) {
    page.open = null;
    drawList();
    return;
  }
  const path = s.kind === 'claude' ? API.lastResponse : API.screen;
  const r = await call(route(path, s.id));
  if (r.status === 401) return unauthorized();
  if (r.status !== 200) return drawSession(s, 'Nothing to show.');
  // A content key has its own revision, so a reply is judged against
  // the last one read for that session, not the list's.
  const applied = page.contentApplied[s.id];
  if (!isCurrent(applied, r.body)) return;
  const same = applied && applied.epoch === r.body.epoch && applied.revision === r.body.revision;
  if (same && !redraw) return;
  page.contentApplied[s.id] = { epoch: r.body.epoch, revision: r.body.revision };
  drawSession(s, r.body.body.text);
}

function drawSession(s, text) {
  const back = el('button', 'Back');
  back.addEventListener('click', () => {
    page.open = null;
    drawList();
  });
  const nodes = [back, el('h2', s.name), el('p', `${s.kind} · ${s.card}`, 'note')];
  if (s.waiting) nodes.push(el('p', `Waiting on you: ${s.waiting_reason || ''}`, 'error'));
  nodes.push(el('pre', text));
  if (page.me.scope === 'control') {
    nodes.push(...replyBox(s));
  }
  // Keep an unsent draft across a redraw.
  const draft = document.getElementById('reply');
  const typed = draft ? draft.value : '';
  show(...nodes);
  const box = document.getElementById('reply');
  if (box && typed) box.value = typed;
}

function replyBox(s) {
  if (s.prompt_refusal) return [el('p', s.prompt_refusal, 'note')];
  const box = el('textarea');
  box.id = 'reply';
  box.setAttribute('aria-label', 'Reply');
  const status = el('p', '', 'note');
  const send = el('button', 'Send', 'primary');
  send.addEventListener('click', () => sendReply(s, box, status));
  return [box, send, status];
}

async function sendReply(s, box, status) {
  const text = box.value.trim();
  if (!text) return;
  // The same text reuses its op, so a retry after a dropped reply is
  // answered from the host's log rather than typed twice.
  let pending = page.pending[s.id];
  if (!pending || pending.text !== text) {
    pending = { op: randomHex(12), text };
    page.pending[s.id] = pending;
  }
  status.textContent = 'Sending…';
  try {
    const r = await call(route(API.send, s.id), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ op: pending.op, text }),
    });
    if (r.status === 200) {
      delete page.pending[s.id];
      box.value = '';
      status.textContent = 'Sent. The session’s card shows progress.';
    } else if (r.status === 401) {
      await unauthorized();
    } else if (r.status === 403 && r.body.error.code === 'scope') {
      const me = await call(API.me);
      if (me.status === 200) page.me = me.body.body;
      status.textContent = 'This device can only read.';
      await readSession(true);
    } else {
      status.textContent = (r.body && r.body.error && r.body.error.message) || 'Not sent.';
    }
  } catch {
    status.textContent = 'No answer. Send again to retry.';
  }
}

// --- staying current

async function tick() {
  if (document.hidden) return;
  try {
    const r = await call(API.waiting);
    if (r.status === 401) return await unauthorized();
    if (r.status !== 200) return;
    const a = page.applied;
    if (!a || a.epoch !== r.body.epoch || a.revision !== r.body.revision) await refresh();
    // A pane can change with the list unchanged; the read also keeps the
    // host's watch on the session warm.
    else if (page.open) await readSession(false);
  } catch {
    // The host is not answering; keep trying.
  }
}

function startPolling(ms) {
  page.pollMs = ms;
  clearInterval(page.pollTimer);
  page.pollTimer = setInterval(tick, ms);
}

// The socket is an enhancement: a change arrives at once. Safari may
// never connect it over a certificate the user accepted, and polling
// carries on either way.
function connectSocket() {
  if (typeof WebSocket === 'undefined') return;
  const socket = new WebSocket(`wss://${location.host}${API.events}`);
  page.socket = socket;
  socket.onopen = () => {
    page.retryMs = RETRY_FIRST;
    startPolling(POLL_SLOW);
  };
  socket.onmessage = (event) => {
    let frame = null;
    try {
      frame = JSON.parse(event.data);
    } catch {
      return;
    }
    if (frame.type === 'changed' || frame.type === 'removed') refresh();
    if (frame.type === 'resync_required') lost();
  };
  socket.onerror = () => {};
  socket.onclose = () => lost();
}

function lost() {
  if (page.socket) {
    page.socket.onclose = null;
    page.socket.close();
    page.socket = null;
  }
  startPolling(POLL_FAST);
  refresh();
  clearTimeout(page.retryTimer);
  page.retryTimer = setTimeout(connectSocket, page.retryMs);
  page.retryMs = Math.min(page.retryMs * 2, RETRY_MAX);
}

if (typeof document !== 'undefined') {
  boot();
}

if (typeof module !== 'undefined') {
  module.exports = { API, parseFragment, deviceName, infer401, isCurrent, route, arrange, ago };
}

//! The Remote devices dialog: who this host is to a device, where it
//! listens, the pairing window with its QR code, and the devices paired
//! so far with their scope and a Revoke. Nothing here decides anything:
//! every change is an action, and the host's state is read back from
//! the core each frame.

use std::net::IpAddr;

use egui::{Context, RichText, Ui};

use super::{DrawCtx, GAP, cards::since_text, theme};
use crate::adapters::remote;
use crate::core::{AppAction, AppCore, invite_url, lan_address};
use crate::ports::remote::Scope;

/// What the dialog edits between frames: the name and port fields, the
/// scope the next pairing grants, and the QR image for the open code.
pub struct RemoteDraft {
    pub name: String,
    pub port: String,
    pub scope: Scope,
    /// The QR texture for the code it was made for.
    qr: Option<(String, egui::TextureHandle)>,
}

impl RemoteDraft {
    #[must_use]
    pub fn open(core: &AppCore) -> Self {
        let identity = core.identity();
        Self {
            name: identity.map(|i| i.server_name.clone()).unwrap_or_default(),
            port: identity
                .map(|i| i.listen.port.to_string())
                .unwrap_or_default(),
            scope: Scope::Read,
            qr: None,
        }
    }
}

/// The dialog's width: the QR and the device rows fit it.
const DIALOG_WIDTH: f32 = 620.0;
/// Pixels per QR module; the quiet zone is the standard four.
const QR_SCALE: usize = 4;
const QR_QUIET: usize = 4;

pub fn show(cx: &mut DrawCtx<'_>, ctx: &Context) {
    let Some(mut draft) = cx.state.remote_dialog.take() else {
        return;
    };
    let mut keep = true;
    egui::Window::new("")
        .id(egui::Id::new("remote-devices"))
        .title_bar(false)
        .collapsible(false)
        .resizable(true)
        .default_width(DIALOG_WIDTH)
        .anchor(egui::Align2::CENTER_CENTER, egui::vec2(0.0, 0.0))
        .show(ctx, |ui| {
            let screen = ctx.content_rect().width();
            ui.set_max_width((screen - 80.0).clamp(320.0, DIALOG_WIDTH));
            ui.spacing_mut().item_spacing = egui::vec2(GAP, GAP);
            ui.label(RichText::new("Remote devices").text_style(theme::brand()));
            ui.add_space(8.0);
            host(cx, ui, &mut draft);
            ui.add_space(8.0);
            pairing(cx, ui, &mut draft);
            ui.add_space(8.0);
            devices(cx, ui);
            ui.add_space(8.0);
            let p = theme::palette(ui);
            ui.label(
                RichText::new(
                    "What a device reads is redacted: the values of a project's secret variables and of its granted sets are replaced by their names. A secret pasted into a prompt, or printed by a tool, that Switchboard never held is not found.",
                )
                .small()
                .color(p.n600),
            );
            ui.horizontal(|ui| {
                if theme::ghost_muted(ui, "Close").clicked() {
                    keep = false;
                }
            });
        });
    if keep {
        cx.state.remote_dialog = Some(draft);
    }
}

/// This host: its name, id and key, and where it listens.
fn host(cx: &mut DrawCtx<'_>, ui: &mut Ui, draft: &mut RemoteDraft) {
    theme::section(ui, "This Mac");
    let Some(identity) = cx.core.identity().cloned() else {
        ui.label("The host has no identity yet; see the log.");
        return;
    };
    ui.horizontal(|ui| {
        let id = ui.label("Name").id;
        let field = ui
            .add(egui::TextEdit::singleline(&mut draft.name).desired_width(240.0))
            .labelled_by(id);
        if field.lost_focus() && draft.name.trim() != identity.server_name {
            cx.dispatch(AppAction::SetServerName(draft.name.clone()));
        }
    });
    ui.label(theme::meta_text(ui, format!("Id {}", identity.server_id)));
    ui.label(theme::meta_text(
        ui,
        format!("Key {}", short_hash(&identity.spki_sha256)),
    ));
    ui.horizontal(|ui| {
        let mut lan = identity.listen.lan;
        if ui
            .checkbox(&mut lan, "Allow devices on the local network")
            .on_hover_text("Off, the port answers this Mac alone; on, it listens on every interface and only paired devices get past /info")
            .changed()
        {
            cx.dispatch(AppAction::SetRemoteListen {
                lan,
                port: identity.listen.port,
            });
        }
        let id = ui.label("Port").id;
        let field = ui
            .add(egui::TextEdit::singleline(&mut draft.port).desired_width(64.0))
            .labelled_by(id);
        if field.lost_focus() {
            match draft.port.trim().parse::<u16>() {
                Ok(port) if port != 0 && port != identity.listen.port => {
                    cx.dispatch(AppAction::SetRemoteListen {
                        lan: identity.listen.lan,
                        port,
                    });
                }
                Ok(_) => {}
                Err(_) => draft.port = identity.listen.port.to_string(),
            }
        }
    });
}

/// The pairing window: open it with a scope, or show the code it holds.
fn pairing(cx: &mut DrawCtx<'_>, ui: &mut Ui, draft: &mut RemoteDraft) {
    theme::section(ui, "Pairing");
    let p = theme::palette(ui);
    if cx.core.identity_rotated() {
        ui.label(
            RichText::new(
                "The host's key was remade at this launch, so every earlier pairing is invalid. Pair each device again.",
            )
            .color(p.accent_2_text),
        );
    }
    let Some(identity) = cx.core.identity().cloned() else {
        return;
    };
    if let Some(window) = cx.core.pairing().cloned() {
        let port = cx.remote_port.unwrap_or(identity.listen.port);
        let lan_ip = lan_address(&identity, remote::local_address());
        let payload = invite_url(&identity, &window, lan_ip, port);
        if draft
            .qr
            .as_ref()
            .is_none_or(|(code, _)| *code != window.code)
        {
            draft.qr = qr_texture(ui.ctx(), &payload).map(|t| (window.code.clone(), t));
        }
        ui.horizontal(|ui| {
            if let Some((_, texture)) = &draft.qr {
                ui.image(egui::load::SizedTexture::from_handle(texture));
            }
            ui.vertical(|ui| {
                ui.label(
                    RichText::new(spaced(&window.code))
                        .text_style(theme::h1())
                        .family(egui::FontFamily::Monospace),
                );
                ui.label(theme::meta_text(
                    ui,
                    format!("Key {}", short_hash(&identity.spki_sha256)),
                ));
                if let Some(ip) = lan_ip {
                    ui.label(theme::meta_text(ui, format!("Address {ip}:{port}")));
                } else {
                    ui.label(theme::meta_text(
                        ui,
                        "The port is Mac-only: turn on \"Allow devices on the local network\" for a phone to reach it.",
                    ));
                }
                ui.label(theme::meta_text(
                    ui,
                    "A browser cannot pin this Mac's key. It will warn about the certificate; proceeding past the warning is the trust step, so proceed only if the address is this Mac's. Pair a browser only on a network you trust. The code works once.",
                ));
                ui.label(theme::meta_text(
                    ui,
                    format!(
                        "Scan, or type the key and the code. Grants {} scope. Open for five minutes or three wrong codes.",
                        window.scope.word()
                    ),
                ));
                ui.horizontal(|ui| {
                    // The QR's text, for a client without a camera (the
                    // command-line browser takes it as one argument).
                    if theme::secondary(ui, "Copy invite")
                        .on_hover_text("The QR code's link, to open or paste into a client")
                        .clicked()
                    {
                        ui.ctx().copy_text(payload.clone());
                    }
                    if theme::secondary(ui, "Stop pairing").clicked() {
                        cx.dispatch(AppAction::ClosePairing);
                    }
                });
            });
        });
    } else {
        ui.horizontal(|ui| {
            ui.radio_value(&mut draft.scope, Scope::Read, "Read-only")
                .on_hover_text("Every view and the screen; nothing is sent into a session");
            ui.radio_value(&mut draft.scope, Scope::Control, "Control")
                .on_hover_text("Reads, and later the commands that type into a session");
            if theme::primary(ui, "Allow pairing for 5 minutes").clicked() {
                cx.dispatch(AppAction::OpenPairing {
                    code: remote::pairing_code(),
                    scope: draft.scope,
                });
            }
        });
    }
}

/// The devices paired so far, each with its scope and a Revoke.
fn devices(cx: &mut DrawCtx<'_>, ui: &mut Ui) {
    theme::section(ui, "Paired devices");
    let devices = cx.core.devices().to_vec();
    if devices.is_empty() {
        ui.label(theme::meta_text(ui, "No device is paired."));
        return;
    }
    egui::Grid::new("remote-devices")
        .num_columns(5)
        .spacing([GAP, GAP])
        .show(ui, |ui| {
            for device in devices {
                ui.label(&device.name);
                let mut scope = device.scope;
                egui::ComboBox::from_id_salt(("remote-scope", device.id))
                    .selected_text(scope.word())
                    .show_ui(ui, |ui| {
                        ui.selectable_value(&mut scope, Scope::Read, "read");
                        ui.selectable_value(&mut scope, Scope::Control, "control");
                    });
                if scope != device.scope {
                    cx.dispatch(AppAction::SetDeviceScope {
                        device: device.id,
                        scope,
                    });
                }
                ui.label(theme::meta_text(
                    ui,
                    format!("paired {}", since_text(device.created)),
                ));
                ui.label(theme::meta_text(
                    ui,
                    match device.last_seen {
                        Some(seen) => format!("seen {}", since_text(seen)),
                        None => "never seen".into(),
                    },
                ));
                if theme::ghost_muted(ui, "Revoke")
                    .on_hover_text("The device's next request fails; pair it again to restore it")
                    .clicked()
                {
                    cx.dispatch(AppAction::RevokeDevice(device.id));
                }
                ui.end_row();
            }
        });
}

/// The QR code for `payload` as a texture: black modules on white with
/// the quiet zone, scaled so a phone reads it from the screen.
fn qr_texture(ctx: &Context, payload: &str) -> Option<egui::TextureHandle> {
    let code = qrcode::QrCode::new(payload.as_bytes()).ok()?;
    let width = code.width();
    let modules = code.to_colors();
    let side = (width + 2 * QR_QUIET) * QR_SCALE;
    let mut pixels = vec![egui::Color32::WHITE; side * side];
    for (i, module) in modules.iter().enumerate() {
        if *module != qrcode::Color::Dark {
            continue;
        }
        let (x, y) = (i % width + QR_QUIET, i / width + QR_QUIET);
        for dy in 0..QR_SCALE {
            for dx in 0..QR_SCALE {
                pixels[(y * QR_SCALE + dy) * side + x * QR_SCALE + dx] = egui::Color32::BLACK;
            }
        }
    }
    let image = egui::ColorImage::new([side, side], pixels);
    Some(ctx.load_texture("remote-pairing-qr", image, egui::TextureOptions::NEAREST))
}

/// The first sixteen hex digits of a key hash in groups of four: what
/// a person compares against the client's screen.
fn short_hash(hex: &str) -> String {
    hex.chars()
        .take(16)
        .collect::<Vec<_>>()
        .chunks(4)
        .map(|c| c.iter().collect::<String>())
        .collect::<Vec<_>>()
        .join(" ")
}

/// "ABCD EFGH": the code in two halves, as it is read aloud.
fn spaced(code: &str) -> String {
    let (a, b) = code.split_at(code.len() / 2);
    format!("{a} {b}")
}

